package com.calookup;

import com.google.gson.Gson;
import java.io.StringReader;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class WikiClientTest
{
	private final Gson gson = new Gson();

	@Test
	public void parsesTheCompletionDocument()
	{
		Map<Integer, Double> rates = WikiClient.parseRates(gson, new StringReader("{\"0\": 69.9, \"1\": 31.3, \"x\": 5, \"7\": null}"));
		assertEquals(2, rates.size());
		assertEquals(69.9, rates.get(0), 0.0001);
		assertEquals(31.3, rates.get(1), 0.0001);
	}

	@Test
	public void parsesAnExtract()
	{
		String json = "{\"batchcomplete\":true,\"query\":{\"pages\":[{\"pageid\":1,\"ns\":0,\"title\":\"Sit Rat\","
			+ "\"extract\":\"Sit Rat is an easy combat achievement.\"}]}}";
		assertEquals("Sit Rat is an easy combat achievement.", WikiClient.parseExtract(gson, json));
	}

	@Test
	public void missingPageIsNull()
	{
		String json = "{\"query\":{\"pages\":[{\"ns\":0,\"title\":\"Nope\",\"missing\":true}]}}";
		assertNull(WikiClient.parseExtract(gson, json));
		assertNull(WikiClient.parseExtract(gson, "{}"));
	}

	@Test
	public void urlsPointAtTheWiki()
	{
		String page = WikiClient.taskPageUrl("You're a wizard").toString();
		assertTrue(page, page.startsWith("https://oldschool.runescape.wiki/w/You're_a_wizard")
			|| page.startsWith("https://oldschool.runescape.wiki/w/You%27re_a_wizard"));
		String spaced = WikiClient.taskPageUrl("Noxious Foe").toString();
		assertTrue(spaced, spaced.startsWith("https://oldschool.runescape.wiki/w/Noxious_Foe"));

		String api = WikiClient.extractUrl("Noxious Foe").toString();
		assertTrue(api, api.startsWith("https://oldschool.runescape.wiki/api.php?"));
		assertTrue(api, api.contains("titles=Noxious%20Foe"));
		assertTrue(api, api.contains("prop=extracts"));
	}

	@Test
	public void bundledSnapshotLoads()
	{
		CompletionRates snapshot = CompletionRates.loadSnapshot(gson);
		assertEquals(CompletionRates.Source.SNAPSHOT, snapshot.getSource());
		assertTrue("snapshot should hold every task", snapshot.size() >= 600);
		assertEquals(69.9, snapshot.rateFor(0), 0.0001);
		assertNull(snapshot.rateFor(999999));
	}
}

package com.calookup;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class WikiSummaryTest
{
	private static final String EXTRACT = "Noxious Foe is an easy combat achievement which requires the player to kill an aberrant spectre.\n"
		+ "This achievement requires 60 Slayer to complete. Boosts can be used.\n\n\n"
		+ "== Strategy ==\n"
		+ "Equipping a nose peg or slayer helmet is required when fighting aberrant spectres.\n\n\n"
		+ "== Other tasks ==\n"
		+ "There are 5 Combat Achievement tasks available.\n\n\n"
		+ "== Trivia ==\n"
		+ "The task's title is a pun.";

	@Test
	public void keepsIntroAndStrategyDropsTheRest()
	{
		WikiSummary s = WikiSummary.parse(EXTRACT);
		assertTrue(s.getIntro().startsWith("Noxious Foe is an easy combat achievement"));
		assertTrue(s.getIntro().endsWith("Boosts can be used."));
		assertEquals("Equipping a nose peg or slayer helmet is required when fighting aberrant spectres.", s.getStrategy());
		assertFalse(s.getStrategy().contains("Trivia"));
		assertFalse(s.getIntro().contains("Other tasks"));
	}

	@Test
	public void pageWithoutHeadingsIsAllIntro()
	{
		WikiSummary s = WikiSummary.parse("Sit Rat is an easy combat achievement.");
		assertEquals("Sit Rat is an easy combat achievement.", s.getIntro());
		assertEquals("", s.getStrategy());
	}

	@Test
	public void emptyExtractIsEmpty()
	{
		assertTrue(WikiSummary.parse("").isEmpty());
		assertTrue(WikiSummary.parse(null).isEmpty());
		assertTrue(WikiSummary.parse("\n\n== Trivia ==\nNothing useful.").isEmpty());
	}

	@Test
	public void truncateStopsAtASentence()
	{
		String text = "First sentence here. Second sentence here. Third sentence is long enough to be cut off.";
		String cut = WikiSummary.truncate(text, 50);
		assertEquals("First sentence here. Second sentence here. …", cut);
		assertEquals(text, WikiSummary.truncate(text, 500));
	}

	@Test
	public void truncateWithoutSentencesFallsBackToWords()
	{
		String text = "word word word word word word word word word word";
		String cut = WikiSummary.truncate(text, 22);
		assertTrue(cut.endsWith("…"));
		assertTrue(cut.length() <= 23);
	}
}

package com.calookup;

import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TaskProgressTest
{
	@Test
	public void killTargets()
	{
		assertEquals(150, TaskProgress.parseKillTarget("Kill Zulrah 150 times."));
		assertEquals(1000, TaskProgress.parseKillTarget("Kill the Kalphite Queen 1,000 times."));
		assertEquals(1, TaskProgress.parseKillTarget("Kill the Hueycoatl once."));
		assertEquals(2, TaskProgress.parseKillTarget("Complete the Gauntlet twice."));
		assertEquals(-1, TaskProgress.parseKillTarget("Kill Zulrah without taking damage."));
		assertEquals(-1, TaskProgress.parseKillTarget(null));
	}

	@Test
	public void speedTargets()
	{
		assertEquals(80, TaskProgress.parseSpeedTargetSeconds("Kill Zulrah in less than 1 minute 20 seconds, without a slayer task."), 0.001);
		assertEquals(54, TaskProgress.parseSpeedTargetSeconds("Kill Zulrah in less than 54 seconds."), 0.001);
		assertEquals(1200, TaskProgress.parseSpeedTargetSeconds("Complete the Theatre of Blood in less than 20 minutes."), 0.001);
		assertEquals(150, TaskProgress.parseSpeedTargetSeconds("Complete Wave 1 in under 2:30."), 0.001);
		assertEquals(90, TaskProgress.parseSpeedTargetSeconds("Kill Vorkath in less than 1 minute and 30 seconds."), 0.001);
		assertEquals(-1, TaskProgress.parseSpeedTargetSeconds("Kill Vorkath 50 times."), 0.001);
	}

	@Test
	public void teamSizes()
	{
		assertEquals("solo", TaskProgress.parseTeamSize("Complete a Chambers of Xeric (Solo) in less than 17 minutes."));
		assertEquals("2 players", TaskProgress.parseTeamSize("Complete the Theatre of Blood (Duo) in less than 26 minutes."));
		assertEquals("3 players", TaskProgress.parseTeamSize("Complete the Theatre of Blood: Hard Mode (Trio) with an overall time of less than 23 minutes."));
		assertEquals("5 players", TaskProgress.parseTeamSize("Complete a Chambers of Xeric: Challenge Mode (5-scale) in less than 25 minutes."));
		assertEquals("8 players", TaskProgress.parseTeamSize("Complete the Tombs of Amascut (expert) within 18 mins in a group of 8."));
		assertEquals(null, TaskProgress.parseTeamSize("Complete the Tombs of Amascut (normal) within 18 mins at any group size."));
		assertEquals(null, TaskProgress.parseTeamSize("Complete the Gauntlet in less than 3 minutes and 45 seconds."));
		assertEquals(1080, TaskProgress.parseSpeedTargetSeconds("Complete the Tombs of Amascut (normal) within 18 mins at any group size."), 0.001);
		assertEquals(1680, TaskProgress.parseSpeedTargetSeconds("Complete the Colosseum with a total time of 28:00 or less."), 0.001);

		assertEquals(List.of("theatre of blood 2 players"), ProgressReader.pbKeysFor("Theatre of Blood", "2 players"));
		assertEquals(List.of("chambers of xeric challenge mode solo"), ProgressReader.pbKeysFor("Chambers of Xeric: Challenge Mode", "solo"));
		assertEquals(ProgressReader.keysFor("Zulrah"), ProgressReader.pbKeysFor("Zulrah", null));
	}

	@Test
	public void timeFormatting()
	{
		assertEquals("1:12", TaskProgress.formatTime(72));
		assertEquals("1:12.6", TaskProgress.formatTime(72.6));
		assertEquals("0:54", TaskProgress.formatTime(54));
		assertEquals("20:00", TaskProgress.formatTime(1200));
	}

	@Test
	public void progressText()
	{
		TaskProgress kc = TaskProgress.forKillCount(61, 150);
		assertEquals("Your kills: 61 / 150", kc.getText());
		assertFalse(kc.isMet());
		assertTrue(TaskProgress.forKillCount(150, 150).isMet());

		TaskProgress pb = TaskProgress.forSpeed(72, 60);
		assertEquals("Under 1:00  ·  your best 1:12", pb.getText());
		assertFalse(pb.isMet());
		assertTrue(TaskProgress.forSpeed(58.8, 60).isMet());
	}

	@Test
	public void configKeysForBosses()
	{
		assertEquals(List.of("zulrah", "the zulrah"), ProgressReader.keysFor("Zulrah"));
		assertEquals(List.of("hueycoatl", "the hueycoatl"), ProgressReader.keysFor("The Hueycoatl").subList(0, 1).equals(List.of("hueycoatl"))
			? List.of("hueycoatl", "the hueycoatl") : ProgressReader.keysFor("The Hueycoatl"));
		assertEquals("chambers of xeric challenge mode", ProgressReader.keysFor("Chambers of Xeric: Challenge Mode").get(0));
		assertEquals("gauntlet", ProgressReader.keysFor("Crystalline Hunllef").get(0));
		assertEquals("barrows chests", ProgressReader.keysFor("Barrows").get(0));
		assertEquals(Arrays.asList("leviathan", "the leviathan"), ProgressReader.keysFor("Leviathan"));
	}

	@Test
	public void pointsLine()
	{
		int[] thresholds = {33, 115, 304, 820, 1465, 2005};
		assertEquals("0 points  ·  33 more for Easy", CombatTaskRepository.pointsLine(0, thresholds));
		assertEquals("296 points  ·  8 more for Hard", CombatTaskRepository.pointsLine(296, thresholds));
		assertEquals("2005 points  ·  Grandmaster reached", CombatTaskRepository.pointsLine(2005, thresholds));
		assertEquals("1 point  ·  32 more for Easy", CombatTaskRepository.pointsLine(1, thresholds));
	}
}

package com.calookup;

import net.runelite.api.gameval.VarPlayerID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CombatTaskRepositoryTest
{
	@Test
	public void completionBitIsTaskIdModulo32InVarpIdOver32()
	{
		int[] varps = new int[CombatTaskRepository.COMPLETED_VARPS.length];
		varps[0] = 1;            // task 0
		varps[1] = 1 << 5;       // task 37
		varps[20] = 1 << 31;     // task 671

		assertTrue(CombatTaskRepository.isCompleted(varps, 0));
		assertFalse(CombatTaskRepository.isCompleted(varps, 1));
		assertTrue(CombatTaskRepository.isCompleted(varps, 37));
		assertFalse(CombatTaskRepository.isCompleted(varps, 36));
		assertTrue(CombatTaskRepository.isCompleted(varps, 671));
	}

	@Test
	public void outOfRangeIdsAreNotCompleted()
	{
		int[] varps = new int[3];
		assertFalse(CombatTaskRepository.isCompleted(varps, -1));
		assertFalse(CombatTaskRepository.isCompleted(varps, 96));
		assertFalse(CombatTaskRepository.isCompleted(new int[0], 0));
	}

	@Test
	public void completionVarpsAreRecognised()
	{
		assertTrue(CombatTaskRepository.isCompletionVarp(VarPlayerID.CA_TASK_COMPLETED_0));
		assertTrue(CombatTaskRepository.isCompletionVarp(VarPlayerID.CA_TASK_COMPLETED_20));
		assertFalse(CombatTaskRepository.isCompletionVarp(VarPlayerID.CA_TRACKING));
		assertEquals(21, CombatTaskRepository.COMPLETED_VARPS.length);
	}
}

package com.calookup;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BossOptionTest
{
	private static final CombatTask Z1 = new CombatTask(1, "Z easy", "", TaskTier.EASY, TaskType.KILL_COUNT, "Zulrah");
	private static final CombatTask Z2 = new CombatTask(2, "Z master", "", TaskTier.MASTER, TaskType.SPEED, "Zulrah");
	private static final CombatTask V1 = new CombatTask(3, "V hard", "", TaskTier.HARD, TaskType.SPEED, "Vorkath");
	private static final CombatTask A1 = new CombatTask(4, "A easy", "", TaskTier.EASY, TaskType.KILL_COUNT, "Araxxor");

	private static List<BossOption> build(Set<Integer> completed, boolean loggedIn)
	{
		List<String> bosses = Arrays.asList("Araxxor", "Vorkath", "Zulrah");
		List<List<CombatTask>> tasksOf = Arrays.asList(
			Collections.singletonList(A1), Collections.singletonList(V1), Arrays.asList(Z1, Z2));
		return BossOption.build(bosses, tasksOf, Arrays.asList(A1, V1, Z1, Z2), completed, loggedIn);
	}

	@Test
	public void allComesFirstThenMostPointsLeft()
	{
		List<BossOption> options = build(new HashSet<>(), true);
		assertEquals(BossOption.ALL, options.get(0).getBoss());
		assertEquals(10, options.get(0).getTotalPoints());
		assertEquals("Zulrah", options.get(1).getBoss());   // 6 points
		assertEquals("Vorkath", options.get(2).getBoss());  // 3
		assertEquals("Araxxor", options.get(3).getBoss());  // 1
	}

	@Test
	public void completedPointsDropABossDownTheList()
	{
		List<BossOption> options = build(new HashSet<>(Arrays.asList(2)), true);
		assertEquals("Vorkath", options.get(1).getBoss());  // 3 left
		// Araxxor and Zulrah both have 1 left; ties are alphabetical.
		assertEquals("Araxxor", options.get(2).getBoss());
		assertEquals("Zulrah", options.get(3).getBoss());
		assertEquals(1, options.get(3).getRemainingPoints());
		assertEquals("Zulrah  ·  1 pt left", options.get(3).getLabel());
		assertEquals(5, options.get(0).getRemainingPoints());
	}

	@Test
	public void loggedOutUsesTotals()
	{
		List<BossOption> options = build(new HashSet<>(Arrays.asList(2)), false);
		assertEquals("Zulrah", options.get(1).getBoss());
		assertEquals("Zulrah  ·  6 pts", options.get(1).getLabel());
		assertTrue(options.get(0).getLabel().startsWith("(All)"));
	}
}

package com.calookup;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TaskArrangerTest
{
	private static final CombatTask EASY_A = new CombatTask(1, "Alpha", "", TaskTier.EASY, TaskType.KILL_COUNT, "Zulrah");
	private static final CombatTask EASY_B = new CombatTask(2, "Bravo", "", TaskTier.EASY, TaskType.MECHANICAL, "Zulrah");
	private static final CombatTask HARD_C = new CombatTask(3, "Charlie", "", TaskTier.HARD, TaskType.SPEED, "Zulrah");
	private static final CombatTask HARD_D = new CombatTask(4, "Delta", "", TaskTier.HARD, TaskType.RESTRICTION, "Zulrah");
	private static final List<CombatTask> TASKS = Arrays.asList(HARD_D, EASY_B, HARD_C, EASY_A);

	private static CompletionRates rates()
	{
		Map<Integer, Double> m = new HashMap<>();
		m.put(1, 40.0);
		m.put(2, 80.0);
		m.put(3, 5.0);
		// 4 has no rate
		return new CompletionRates(m, CompletionRates.Source.SNAPSHOT, null, null);
	}

	@Test
	public void tiersAreKeptInOrderAndSortedByRate()
	{
		Map<TaskTier, List<CombatTask>> out = TaskArranger.arrange(TASKS, new HashSet<>(), rates(),
			TaskArranger.Filter.ALL, TaskArranger.SortMode.WIKI_RATE);
		assertEquals(Arrays.asList(TaskTier.EASY, TaskTier.HARD), new java.util.ArrayList<>(out.keySet()));
		assertEquals(Arrays.asList(EASY_B, EASY_A), out.get(TaskTier.EASY));
		// Unknown rate sorts last.
		assertEquals(Arrays.asList(HARD_C, HARD_D), out.get(TaskTier.HARD));
	}

	@Test
	public void rarestFirstPutsUnknownLast()
	{
		Map<TaskTier, List<CombatTask>> out = TaskArranger.arrange(TASKS, new HashSet<>(), rates(),
			TaskArranger.Filter.ALL, TaskArranger.SortMode.WIKI_RATE_ASC);
		assertEquals(Arrays.asList(EASY_A, EASY_B), out.get(TaskTier.EASY));
		assertEquals(Arrays.asList(HARD_C, HARD_D), out.get(TaskTier.HARD));
	}

	@Test
	public void nameSortIsAlphabetical()
	{
		Map<TaskTier, List<CombatTask>> out = TaskArranger.arrange(TASKS, new HashSet<>(), rates(),
			TaskArranger.Filter.ALL, TaskArranger.SortMode.NAME);
		assertEquals(Arrays.asList(EASY_A, EASY_B), out.get(TaskTier.EASY));
		assertEquals(Arrays.asList(HARD_C, HARD_D), out.get(TaskTier.HARD));
	}

	@Test
	public void incompleteFilterKeepsEmptyTierSections()
	{
		Set<Integer> done = new HashSet<>(Arrays.asList(1, 2));
		Map<TaskTier, List<CombatTask>> out = TaskArranger.arrange(TASKS, done, rates(),
			TaskArranger.Filter.INCOMPLETE, TaskArranger.SortMode.NAME);
		assertTrue(out.containsKey(TaskTier.EASY));
		assertTrue(out.get(TaskTier.EASY).isEmpty());
		assertEquals(Arrays.asList(HARD_C, HARD_D), out.get(TaskTier.HARD));
	}

	@Test
	public void countsAndPoints()
	{
		Set<Integer> done = new HashSet<>(Arrays.asList(1, 3));
		assertEquals(2, TaskArranger.countDone(TASKS, done));
		assertEquals(TaskTier.EASY.getPoints() + TaskTier.HARD.getPoints(), TaskArranger.pointsDone(TASKS, done));
		assertEquals(2 * TaskTier.EASY.getPoints() + 2 * TaskTier.HARD.getPoints(), TaskArranger.pointsTotal(TASKS));
	}

	@Test
	public void comboSearchPrefersPrefixMatches()
	{
		List<String> items = Arrays.asList("Chambers of Xeric", "Zulrah", "Zalcano", "Vorkath", "TzKal-Zuk");
		assertEquals(Arrays.asList("Zulrah", "Zalcano", "TzKal-Zuk"), SearchableComboBox.matching(items, "z"));
		assertEquals(Arrays.asList("Zulrah", "TzKal-Zuk"), SearchableComboBox.matching(items, "ZU"));
		assertEquals(items, SearchableComboBox.matching(items, "  "));
		assertTrue(SearchableComboBox.matching(items, "nope").isEmpty());
	}
}

package com.calookup;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BossMatcherTest
{
	@Test
	public void normalizeStripsTagsCaseAndLeadingThe()
	{
		assertEquals("zulrah", BossMatcher.normalize("<col=ffff00>Zulrah</col>"));
		assertEquals("leviathan", BossMatcher.normalize("The Leviathan"));
		assertEquals("vet'ion", BossMatcher.normalize("Vet’ion"));
		assertEquals("chambers of xeric: challenge mode", BossMatcher.normalize("  Chambers  of Xeric: Challenge Mode "));
		assertEquals("", BossMatcher.normalize(null));
	}

	@Test
	public void directNameIsAlwaysACandidate()
	{
		List<String> groups = BossMatcher.groupsFor("Zulrah");
		assertEquals(1, groups.size());
		assertEquals("zulrah", groups.get(0));
	}

	@Test
	public void raidRoomsMapToEveryRaidMode()
	{
		List<String> groups = BossMatcher.groupsFor("Great Olm");
		assertTrue(groups.contains("Chambers of Xeric"));
		assertTrue(groups.contains("Chambers of Xeric: Challenge Mode"));
		assertEquals("Chambers of Xeric", groups.get(0));

		groups = BossMatcher.groupsFor("Verzik Vitur");
		assertTrue(groups.contains("Theatre of Blood"));
		assertTrue(groups.contains("Theatre of Blood: Hard Mode"));
		assertTrue(groups.contains("Theatre of Blood: Entry Mode"));

		groups = BossMatcher.groupsFor("Tumeken's Warden");
		assertTrue(groups.contains("Tombs of Amascut"));
		assertTrue(groups.contains("Tombs of Amascut: Expert Mode"));
	}

	@Test
	public void jadInTheInfernoBelongsToTwoGroups()
	{
		List<String> groups = BossMatcher.groupsFor("JalTok-Jad");
		assertTrue(groups.contains("TzKal-Zuk"));
		assertTrue(groups.contains("TzHaar-Ket-Rak's Challenges"));
	}

	@Test
	public void lesserWildernessFormsMapToTheirBoss()
	{
		assertEquals("Callisto", BossMatcher.aliasesFor("Artio").get(0));
		assertEquals("Venenatis", BossMatcher.aliasesFor("Spindel").get(0));
		assertEquals("Vet'ion", BossMatcher.aliasesFor("Calvar'ion").get(0));
	}

	@Test
	public void unknownNpcHasNoAliases()
	{
		assertTrue(BossMatcher.aliasesFor("Man").isEmpty());
		assertTrue(BossMatcher.groupsFor("").isEmpty());
		assertFalse(BossMatcher.groupsFor("Man").isEmpty());
	}

	@Test
	public void aliasTableUsesConsistentGroupNames()
	{
		// Every aliased group must survive normalisation unchanged apart from case/"the",
		// so it can be resolved against the live task list.
		for (String npc : BossMatcher.allAliasedNpcNames())
		{
			for (String group : BossMatcher.aliasesFor(npc))
			{
				assertFalse("empty group for " + npc, group.trim().isEmpty());
				assertTrue(BossMatcher.sameGroup(group, group.toUpperCase()));
			}
		}
	}
}

