import lombok.extern.slf4j.Slf4j;

/**
 * The share of players who have completed each task, keyed by task ID.
 * <p>
 * The plugin ships a snapshot of the wiki's numbers so the panel is useful offline or when the
 * wiki is off-limits, and replaces it with the live document when that can be fetched. Each
 * copy knows when the wiki last regenerated the data, which is what the footer reports.
 */
@Slf4j
final class CompletionRates
{
	enum Source
	{
		/** Nothing loaded at all. */
		NONE,
		/** The copy bundled with the plugin. */
		SNAPSHOT,
		/** Fetched from the wiki during this session. */
		WIKI
	}

	static final String SNAPSHOT_RESOURCE = "completion-snapshot.json";
	/** The wiki revision the bundled snapshot was taken from. */
	static final Instant SNAPSHOT_DATA_DATE = Instant.parse("2026-08-31T00:44:46Z");

	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("d MMM yyyy");

	static final CompletionRates EMPTY = new CompletionRates(Collections.emptyMap(), Source.NONE, null, null);

	private final Map<Integer, Double> rates;
	private final Source source;
	private final Instant fetchedAt;
	private final Instant dataDate;

	CompletionRates(Map<Integer, Double> rates, Source source, Instant fetchedAt, Instant dataDate)
	{
		this.rates = Collections.unmodifiableMap(rates);
		this.source = source;
		this.fetchedAt = fetchedAt;
		this.dataDate = dataDate;
	}

	/** Loads the bundled snapshot through {@code getResourceAsStream}, as the plugin hub requires. */
	static CompletionRates loadSnapshot(Gson gson)
	{
		try (InputStream in = CompletionRates.class.getResourceAsStream(SNAPSHOT_RESOURCE))
		{
			if (in == null)
			{
				log.warn("Bundled completion snapshot is missing");
				return EMPTY;
			}
			Map<Integer, Double> parsed = WikiClient.parseRates(gson, new InputStreamReader(in, StandardCharsets.UTF_8));
			return new CompletionRates(parsed, Source.SNAPSHOT, null, SNAPSHOT_DATA_DATE);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled completion snapshot could not be read", e);
			return EMPTY;
		}
	}

	static CompletionRates fromWiki(Map<Integer, Double> rates, Instant dataDate)
	{
		return new CompletionRates(rates, Source.WIKI, Instant.now(), dataDate);
	}

	/** @return the percentage of players who completed the task, or null if unknown */
	Double rateFor(int taskId)
	{
		return rates.get(taskId);
	}

	int size()
	{
		return rates.size();
	}

	Source getSource()
	{
		return source;
	}

	/** When this copy was downloaded, or null for the bundled snapshot. */
	Instant getFetchedAt()
	{
		return fetchedAt;
	}

	/** When the wiki last regenerated the numbers, or null if unknown. */
	Instant getDataDate()
	{
		return dataDate;
	}

	/** The data date as "31 Aug 2026", or null. */
	String getDataDateText()
	{
		// The wiki stamps revisions in UTC; keep the same calendar day it shows.
		return dataDate == null ? null : DATE.format(dataDate.atZone(ZoneOffset.UTC));
	}
}

package com.calookup;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.Predicate;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.FontManager;

/**
 * A collapsible tier heading with a coloured ribbon, the player's count for the tier and a
 * thin progress line, followed by the tier's task rows.
 * <p>
 * Rows are attached once per sort order ({@link #setRows}) and a filter only flips their
 * visibility ({@link #applyFilter}), which keeps Swing's cached sizes valid and makes
 * switching filters cheap even with hundreds of rows.
 */
class TierSection extends JPanel
{
	private final TaskTier tier;
	private final LookupPanel owner;

	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	private final Ribbon ribbon = new Ribbon();
	private final JLabel title = new JLabel();
	private final JLabel count = new JLabel("", SwingConstants.RIGHT);
	private final RateBar progress;
	private final JPanel rows = new JPanel();
	private final JLabel empty = new JLabel();

	private Theme theme;
	private boolean collapsed;
	private boolean anyVisible;

	TierSection(TaskTier tier, LookupPanel owner, Theme theme)
	{
		this.tier = tier;
		this.owner = owner;
		this.theme = theme;

		setOpaque(false);
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		header.setBorder(BorderFactory.createEmptyBorder(6, 4, 4, 6));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));

		header.add(ribbon, BorderLayout.WEST);

		JPanel middle = new JPanel();
		middle.setOpaque(false);
		middle.setLayout(new BoxLayout(middle, BoxLayout.Y_AXIS));
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setText(tier.getDisplayName());
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		middle.add(title);
		middle.add(Box.createVerticalStrut(3));
		progress = new RateBar(3, theme.tierColor(tier), theme.getTrack());
		progress.setAlignmentX(Component.LEFT_ALIGNMENT);
		middle.add(progress);
		header.add(middle, BorderLayout.CENTER);

		count.setFont(FontManager.getRunescapeSmallFont());
		header.add(count, BorderLayout.EAST);

		MouseAdapter toggle = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				owner.toggleCollapsed(tier);
			}
		};
		header.addMouseListener(toggle);
		title.addMouseListener(toggle);
		count.addMouseListener(toggle);
		middle.addMouseListener(toggle);
		add(header);

		rows.setOpaque(false);
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(rows);

		empty.setFont(FontManager.getRunescapeSmallFont());
		empty.setBorder(BorderFactory.createEmptyBorder(2, 24, 6, 6));
		empty.setAlignmentX(Component.LEFT_ALIGNMENT);
		empty.setVisible(false);
		add(empty);

		applyTheme(theme);
	}

	TaskTier getTier()
	{
		return tier;
	}

	void applyTheme(Theme theme)
	{
		this.theme = theme;
		Color tierColor = theme.tierColor(tier);
		header.setBackground(theme.getBackground());
		header.setOpaque(true);
		title.setForeground(tierColor);
		count.setForeground(theme.getMuted());
		empty.setForeground(theme.getMuted());
		progress.setColors(tierColor, theme.getTrack());
		ribbon.setColor(tierColor);
		repaint();
	}

	/** Attaches every row of this tier in display order. Rows keep their own spacing. */
	void setRows(List<TaskRow> ordered)
	{
		rows.removeAll();
		for (TaskRow row : ordered)
		{
			rows.add(row);
		}
	}

	/**
	 * Shows only the rows the filter accepts and refreshes the count line.
	 *
	 * @param show     which tasks stay visible
	 * @param done     completed tasks in this tier for this boss, before filtering
	 * @param total    all tasks in this tier for this boss
	 * @param filter   the active filter, used for the "nothing here" message
	 * @param loggedIn whether completion is known
	 */
	void applyFilter(Predicate<CombatTask> show, int done, int total, TaskArranger.Filter filter, boolean loggedIn)
	{
		anyVisible = false;
		for (Component c : rows.getComponents())
		{
			if (c instanceof TaskRow)
			{
				boolean visible = show.test(((TaskRow) c).getTask());
				if (c.isVisible() != visible)
				{
					c.setVisible(visible);
				}
				anyVisible |= visible;
			}
		}
		updateCounts(done, total, loggedIn);
		if (filter == TaskArranger.Filter.INCOMPLETE)
		{
			empty.setText("Every " + tier.getDisplayName().toLowerCase() + " task done. Nice.");
		}
		else
		{
			empty.setText("No tasks.");
		}
		refreshVisibility();
	}

	/** Refreshes the count and progress line without touching the rows. */
	void updateCounts(int done, int total, boolean loggedIn)
	{
		if (loggedIn)
		{
			count.setText(done + " / " + total);
			progress.setFraction(total == 0 ? 0 : (double) done / total);
		}
		else
		{
			count.setText(total + (total == 1 ? " task" : " tasks"));
			progress.setFraction(0);
		}
	}

	void setCollapsed(boolean collapsed)
	{
		this.collapsed = collapsed;
		ribbon.setCollapsed(collapsed);
		refreshVisibility();
	}

	private void refreshVisibility()
	{
		rows.setVisible(!collapsed);
		empty.setVisible(!collapsed && !anyVisible);
	}

	/** The coloured bar with a small triangle showing whether the section is open. */
	private static class Ribbon extends JComponent
	{
		private Color color = Color.GRAY;
		private boolean collapsed;

		Ribbon()
		{
			Dimension d = new Dimension(12, 22);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
			setOpaque(false);
		}

		void setColor(Color color)
		{
			this.color = color;
			repaint();
		}

		void setCollapsed(boolean collapsed)
		{
			this.collapsed = collapsed;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			int h = getHeight();
			g2.fillRoundRect(0, 0, 4, h, 4, 4);
			int cx = 9;
			int cy = h / 2;
			int[] xs;
			int[] ys;
			if (collapsed)
			{
				xs = new int[]{cx - 2, cx + 2, cx - 2};
				ys = new int[]{cy - 4, cy, cy + 4};
			}
			else
			{
				xs = new int[]{cx - 4, cx + 4, cx};
				ys = new int[]{cy - 2, cy - 2, cy + 3};
			}
			g2.fillPolygon(xs, ys, 3);
			g2.dispose();
		}
	}
}

package com.calookup;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.config.ConfigManager;

/**
 * Reads the player's kill counts and personal bests that RuneLite's Chat Commands plugin
 * records per character, and matches them to kill-count and speed tasks.
 * <p>
 * Chat Commands stores kill counts under the {@code killcount} group and personal bests under
 * {@code personalbest}, keyed by the boss name from the game's own message, lower-cased. Most
 * Combat Achievement boss groups use the same name; the exceptions are listed here.
 */
final class ProgressReader
{
	static final String KC_GROUP = "killcount";
	static final String PB_GROUP = "personalbest";

	/** Boss group (normalised) to the config keys Chat Commands might have used, in order of preference. */
	private static final Map<String, List<String>> KEYS = new HashMap<>();

	private static void keys(String boss, String... candidates)
	{
		KEYS.put(BossMatcher.normalize(boss), List.of(candidates));
	}

	static
	{
		keys("Chambers of Xeric", "chambers of xeric");
		keys("Chambers of Xeric: Challenge Mode", "chambers of xeric challenge mode");
		keys("Theatre of Blood", "theatre of blood");
		keys("Theatre of Blood: Hard Mode", "theatre of blood hard mode");
		keys("Theatre of Blood: Entry Mode", "theatre of blood entry mode", "theatre of blood story mode");
		keys("Tombs of Amascut", "tombs of amascut");
		keys("Tombs of Amascut: Expert Mode", "tombs of amascut expert mode");
		keys("Tombs of Amascut: Entry Mode", "tombs of amascut entry mode");
		keys("Crystalline Hunllef", "gauntlet");
		keys("Corrupted Hunllef", "corrupted gauntlet");
		keys("Barrows", "barrows chests");
		keys("Moons of Peril", "lunar chest", "lunar chests");
		keys("Fortis Colosseum", "sol heredit");
		keys("The Nightmare", "nightmare");
		keys("Phosani's Nightmare", "phosani's nightmare");
		keys("The Hueycoatl", "hueycoatl");
		keys("The Mimic", "mimic");
		keys("Leviathan", "leviathan", "the leviathan");
		keys("Whisperer", "whisperer", "the whisperer");
		keys("Royal Titans", "royal titans", "the royal titans");
		keys("TzHaar-Ket-Rak's Challenges", "tzhaar-ket-rak's challenges");
	}

	private final ConfigManager configManager;

	ProgressReader(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/** The config keys to try for a boss group, most specific first. */
	static List<String> keysFor(String boss)
	{
		List<String> known = KEYS.get(BossMatcher.normalize(boss));
		if (known != null)
		{
			return known;
		}
		String lower = boss.toLowerCase(Locale.ROOT).trim();
		List<String> out = new ArrayList<>(3);
		out.add(lower);
		if (lower.startsWith("the "))
		{
			out.add(lower.substring(4));
		}
		else
		{
			out.add("the " + lower);
		}
		return Collections.unmodifiableList(out);
	}

	/**
	 * @return progress for every task that has a readable target and a recorded number, by task ID
	 */
	Map<Integer, TaskProgress> read(List<CombatTask> tasks)
	{
		Map<Integer, TaskProgress> out = new HashMap<>();
		Map<String, Integer> kcByBoss = new HashMap<>();
		Map<String, Double> pbByBoss = new HashMap<>();
		for (CombatTask task : tasks)
		{
			if (task.getType() == TaskType.KILL_COUNT)
			{
				int target = TaskProgress.parseKillTarget(task.getDescription());
				if (target <= 0)
				{
					continue;
				}
				Integer kc = kcByBoss.computeIfAbsent(task.getBoss(), this::killCount);
				if (kc != null)
				{
					out.put(task.getId(), TaskProgress.forKillCount(kc, target));
				}
			}
			else if (task.getType() == TaskType.SPEED)
			{
				double target = TaskProgress.parseSpeedTargetSeconds(task.getDescription());
				if (target <= 0)
				{
					continue;
				}
				// A "(Duo)" or "(5-scale)" task only counts a best set at that team size; the
				// client records those separately, so never fall back to the overall best.
				String size = TaskProgress.parseTeamSize(task.getDescription());
				String cacheKey = size == null ? task.getBoss() : task.getBoss() + "|" + size;
				Double pb = pbByBoss.computeIfAbsent(cacheKey, k -> personalBest(task.getBoss(), size));
				if (pb != null)
				{
					out.put(task.getId(), TaskProgress.forSpeed(pb, target));
				}
			}
		}
		return out;
	}

	private Integer killCount(String boss)
	{
		for (String key : keysFor(boss))
		{
			Integer kc = configManager.getRSProfileConfiguration(KC_GROUP, key, Integer.class);
			if (kc != null && kc > 0)
			{
				return kc;
			}
		}
		return null;
	}

	/** Config keys for a boss's PB at a team size, e.g. {@code theatre of blood 2 players}. */
	static List<String> pbKeysFor(String boss, String teamSize)
	{
		if (teamSize == null)
		{
			return keysFor(boss);
		}
		List<String> out = new ArrayList<>();
		for (String key : keysFor(boss))
		{
			out.add(key + " " + teamSize);
		}
		return Collections.unmodifiableList(out);
	}

	private Double personalBest(String boss, String teamSize)
	{
		for (String key : pbKeysFor(boss, teamSize))
		{
			Double pb = configManager.getRSProfileConfiguration(PB_GROUP, key, Double.class);
			if (pb != null && pb > 0)
			{
				return pb;
			}
		}
		return null;
	}
}

package com.calookup;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.client.util.Text;

/**
 * Maps the name of an NPC the player right-clicked to the Combat Achievement boss group(s)
 * its tasks are filed under.
 * <p>
 * Most bosses are filed under their own name, so the fallback is a direct name match. This
 * table covers the rest: raid rooms, minions, forms, brothers and the odd renamed group. NPC
 * names are matched after {@link #normalize(String)}, so capitalisation, colour tags and a
 * leading "The" do not matter. Nothing here is a user-supplied ID.
 */
final class BossMatcher
{
	private static final Map<String, List<String>> ALIASES = new HashMap<>();

	private static void alias(String group, String... npcNames)
	{
		for (String npc : npcNames)
		{
			ALIASES.computeIfAbsent(normalize(npc), k -> new ArrayList<>()).add(group);
		}
	}

	private static void aliasAll(String[] groups, String... npcNames)
	{
		for (String group : groups)
		{
			alias(group, npcNames);
		}
	}

	static
	{
		// Chambers of Xeric
		String[] cox = {"Chambers of Xeric", "Chambers of Xeric: Challenge Mode"};
		aliasAll(cox, "Great Olm", "Great Olm (Left claw)", "Great Olm (Right claw)", "Tekton", "Tekton (enraged)",
			"Vasa Nistirio", "Vanguard", "Vespula", "Vespine soldier", "Muttadile", "Ice demon", "Skeletal Mystic",
			"Abyssal portal", "Deathly ranger", "Deathly mage", "Scavenger beast", "Jewelled Crab",
			"Lux grub", "Guardian");
		aliasAll(cox, "Lizardman shaman");

		// Theatre of Blood
		String[] tob = {"Theatre of Blood", "Theatre of Blood: Entry Mode", "Theatre of Blood: Hard Mode"};
		aliasAll(tob, "The Maiden of Sugadinti", "Pestilent Bloat", "Nylocas Vasilias", "Nylocas Prinkipas",
			"Nylocas Ischyros", "Nylocas Toxobolos", "Nylocas Hagios", "Sotetseg", "Xarpus", "Verzik Vitur",
			"Nylocas Matomenos", "Blood spawn");

		// Tombs of Amascut
		String[] toa = {"Tombs of Amascut", "Tombs of Amascut: Entry Mode", "Tombs of Amascut: Expert Mode"};
		aliasAll(toa, "Ba-Ba", "Akkha", "Akkha's Shadow", "Kephri", "Zebak", "Tumeken's Warden", "Elidinis' Warden",
			"Obelisk", "Scarab Swarm", "Soldier Scarab", "Spitting Scarab", "Arcane Scarab", "Baboon Brawler",
			"Baboon Thrower", "Baboon Mage", "Baboon Shaman", "Volatile Baboon", "Cursed Baboon", "Crocodile");

		// Inferno, Fight Caves and TzHaar-Ket-Rak's Challenges
		alias("TzKal-Zuk", "TzKal-Zuk", "Jal-Zek", "Jal-Xil", "Jal-ImKot", "Jal-AkRek-Mej", "Jal-AkRek-Ket",
			"Jal-AkRek-Xil", "Jal-MejRah", "Jal-Nib", "Jal-Ak", "Jal-MejJak", "Ancestral Glyph", "Rocky support");
		alias("TzTok-Jad", "TzTok-Jad", "Tz-Kih", "Tz-Kek", "Tok-Xil", "Yt-MejKot", "Ket-Zek", "Yt-HurKot");
		aliasAll(new String[]{"TzHaar-Ket-Rak's Challenges", "TzKal-Zuk"}, "JalTok-Jad");
		alias("TzHaar-Ket-Rak's Challenges", "TzHaar-Ket-Rak");

		// Gauntlet
		alias("Crystalline Hunllef", "Crystalline Hunllef");
		alias("Corrupted Hunllef", "Corrupted Hunllef");

		// Barrows
		alias("Barrows", "Ahrim the Blighted", "Dharok the Wretched", "Guthan the Infested", "Karil the Tainted",
			"Torag the Corrupted", "Verac the Defiled");

		// Grotesque Guardians
		alias("Grotesque Guardians", "Dusk", "Dawn");

		// God Wars Dungeon
		alias("Commander Zilyana", "Starlight", "Bree", "Growler");
		alias("General Graardor", "Sergeant Strongstack", "Sergeant Steelwill", "Sergeant Grimspike");
		alias("K'ril Tsutsaroth", "Tstanon Karlak", "Zakl'n Gritch", "Balfrug Kreeyath");
		alias("Kree'arra", "Flight Kilisa", "Flockleader Geerin", "Wingman Skree");
		alias("Nex", "Fumus", "Umbra", "Cruor", "Glacies");

		// Wilderness bosses and their lesser forms
		alias("Callisto", "Artio");
		alias("Venenatis", "Spindel");
		alias("Vet'ion", "Calvar'ion", "Vet'ion Reborn", "Calvar'ion Reborn", "Skeleton Hellhound",
			"Greater Skeleton Hellhound");
		alias("Corporeal Beast", "Dark energy core");

		// Nightmare
		alias("The Nightmare", "The Nightmare", "Parasite", "Husk", "Sleepwalker", "Totem");
		alias("Phosani's Nightmare", "Phosani's Nightmare");

		// Desert Treasure II
		alias("Leviathan", "The Leviathan");
		alias("Whisperer", "The Whisperer");

		// Moons of Peril
		alias("Moons of Peril", "Blood Moon", "Blue Moon", "Eclipse Moon");

		// Royal Titans
		alias("Royal Titans", "Branda the Fire Queen", "Eldric the Ice King");

		// Fortis Colosseum
		alias("Fortis Colosseum", "Sol Heredit", "Fremennik warband archer", "Fremennik warband berserker",
			"Fremennik warband seer", "Serpent shaman", "Jaguar warrior", "Javelin Colossus", "Manticore",
			"Shockwave Colossus", "Minotaur", "Minimus");

		// Slayer monsters with variant names
		alias("Bloodveld", "Mutated Bloodveld");
		alias("Gargoyle", "Marble gargoyle");
		alias("Kurask", "King kurask");
		alias("Black Dragon", "Black dragon");
		alias("Wyrm", "Wyrmling");
		alias("Kraken", "Whirlpool");
		alias("Alchemical Hydra", "Alchemical Hydra");
		alias("Hespori", "Flower");
		alias("Zalcano", "Zalcano");
		alias("Tempoross", "Tempoross", "Spirit pool");
		alias("Wintertodt", "Wintertodt", "Incapacitated Wintertodt");
		alias("The Hueycoatl", "Hueycoatl");
		alias("The Mimic", "Mimic");
		alias("Scurrius", "Giant rat");
		alias("Duke Sucellus", "Duke Sucellus");
		alias("Vardorvis", "Vardorvis");
		alias("Yama", "Judge of Yama", "Yama");

		// The giant cave tasks
		alias("Giants", "Hill Giant", "Moss giant", "Fire giant");
	}

	private BossMatcher()
	{
	}

	/**
	 * Lower-cases, strips colour tags, unifies apostrophes, collapses whitespace and drops a
	 * leading "the". Applied to both NPC names and boss group names before comparing.
	 */
	static String normalize(String name)
	{
		if (name == null)
		{
			return "";
		}
		String n = Text.removeTags(name)
			.replace('’', '\'')
			.replace('‘', '\'')
			.toLowerCase(Locale.ROOT)
			.trim()
			.replaceAll("\\s+", " ");
		if (n.startsWith("the "))
		{
			n = n.substring(4);
		}
		return n;
	}

	/**
	 * @param npcName the NPC's name as shown in the menu (tags allowed)
	 * @return the boss group names this NPC belongs to, in priority order. Empty if none.
	 * The names are as written in the alias table; callers should resolve them against the
	 * live task list with {@link BossMatcher#normalize(String)} so a renamed group still matches.
	 */
	static List<String> groupsFor(String npcName)
	{
		String key = normalize(npcName);
		if (key.isEmpty())
		{
			return Collections.emptyList();
		}
		Set<String> groups = new LinkedHashSet<>();
		List<String> aliased = ALIASES.get(key);
		if (aliased != null)
		{
			groups.addAll(aliased);
		}
		// Direct match: most bosses are filed under their own name.
		groups.add(key);
		return Collections.unmodifiableList(new ArrayList<>(groups));
	}

	/** Only the explicitly aliased groups, used by tests. */
	static List<String> aliasesFor(String npcName)
	{
		List<String> aliased = ALIASES.get(normalize(npcName));
		return aliased == null ? Collections.emptyList() : Collections.unmodifiableList(aliased);
	}

	static List<String> allAliasedNpcNames()
	{
		List<String> names = new ArrayList<>(ALIASES.keySet());
		Collections.sort(names);
		return names;
	}

	static boolean sameGroup(String a, String b)
	{
		return normalize(a).equals(normalize(b));
	}
}

package com.calookup;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
