package com.calookup;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Pure filtering and sorting of a boss's tasks. Tier sections are always kept; the options
 * only decide which rows appear inside each section and in what order.
 * <p>
 * Public because {@link Filter} and {@link SortMode} are config value types, and RuneLite's
 * config proxy lives in another module that can only see public classes.
 */
public final class TaskArranger
{
	public enum Filter
	{
		ALL("All"),
		INCOMPLETE("Incomplete");

		private final String label;

		Filter(String label)
		{
			this.label = label;
		}

		String getLabel()
		{
			return label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	public enum SortMode
	{
		WIKI_RATE("Most completed first"),
		WIKI_RATE_ASC("Rarest first"),
		NAME("Name A-Z");

		private final String label;

		SortMode(String label)
		{
			this.label = label;
		}

		String getLabel()
		{
			return label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private TaskArranger()
	{
	}

	/**
	 * Groups the tasks by tier, applying the filter and sort inside each tier. Tiers with no
	 * tasks for this boss are omitted; tiers whose tasks were all filtered out are kept with an
	 * empty list so the section can say "all done".
	 */
	static Map<TaskTier, List<CombatTask>> arrange(List<CombatTask> tasks, Set<Integer> completed,
		CompletionRates rates, Filter filter, SortMode sort)
	{
		Map<TaskTier, List<CombatTask>> out = new EnumMap<>(TaskTier.class);
		for (CombatTask task : tasks)
		{
			out.computeIfAbsent(task.getTier(), t -> new ArrayList<>());
			if (matches(task, completed, filter))
			{
				out.get(task.getTier()).add(task);
			}
		}
		Comparator<CombatTask> comparator = comparator(rates, sort);
		for (List<CombatTask> list : out.values())
		{
			list.sort(comparator);
		}
		return out;
	}

	static boolean matches(CombatTask task, Set<Integer> completed, Filter filter)
	{
		if (filter == Filter.INCOMPLETE)
		{
			return !completed.contains(task.getId());
		}
		return true;
	}

	static Comparator<CombatTask> comparator(CompletionRates rates, SortMode sort)
	{
		Comparator<CombatTask> byName = Comparator.comparing(CombatTask::getName, String.CASE_INSENSITIVE_ORDER);
		Comparator<CombatTask> byRateDesc = Comparator.comparingDouble((CombatTask t) ->
		{
			Double r = rates.rateFor(t.getId());
			return r == null ? 1 : -r;
		});
		Comparator<CombatTask> byRateAsc = Comparator.comparingDouble((CombatTask t) ->
		{
			Double r = rates.rateFor(t.getId());
			return r == null ? Double.MAX_VALUE : r;
		});

		switch (sort)
		{
			case WIKI_RATE_ASC:
				return byRateAsc.thenComparing(byName);
			case NAME:
				return byName;
			case WIKI_RATE:
			default:
				return byRateDesc.thenComparing(byName);
		}
	}

	/** @return how many of the tasks are completed */
	static int countDone(List<CombatTask> tasks, Set<Integer> completed)
	{
		int n = 0;
		for (CombatTask task : tasks)
		{
			if (completed.contains(task.getId()))
			{
				n++;
			}
		}
		return n;
	}

	/** @return points earned from the completed tasks in the list */
	static int pointsDone(List<CombatTask> tasks, Set<Integer> completed)
	{
		int n = 0;
		for (CombatTask task : tasks)
		{
			if (completed.contains(task.getId()))
			{
				n += task.getTier().getPoints();
			}
		}
		return n;
	}

	/** @return total points available from the list */
	static int pointsTotal(List<CombatTask> tasks)
	{
		int n = 0;
		for (CombatTask task : tasks)
		{
			n += task.getTier().getPoints();
		}
		return n;
	}
}

package com.calookup;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * A short, plain-text explanation of a task built from the wiki's page extract: the opening
 * paragraph plus the strategy section, with trivia and other chatter dropped.
 */
public final class WikiSummary
{
	/** Sections kept from the wiki page, lower-cased. */
	private static final Set<String> KEEP_SECTIONS = new HashSet<>(Arrays.asList(
		"strategy", "strategies", "guide", "tips", "method", "methods", "mechanics", "requirements",
		"notes", "how to complete", "walkthrough"));

	/** Matches {@code == Heading ==} lines produced by exsectionformat=wiki. */
	private static final Pattern HEADING = Pattern.compile("(?m)^\\s*(={2,})\\s*(.+?)\\s*\\1\\s*$");

	public static final int MAX_INTRO_CHARS = 700;
	public static final int MAX_STRATEGY_CHARS = 1100;

	private final String intro;
	private final String strategy;

	WikiSummary(String intro, String strategy)
	{
		this.intro = intro == null ? "" : intro;
		this.strategy = strategy == null ? "" : strategy;
	}

	/** The page's opening paragraph(s), already trimmed to a readable length. */
	public String getIntro()
	{
		return intro;
	}

	/** The strategy/tips text, or empty if the page has none. */
	public String getStrategy()
	{
		return strategy;
	}

	public boolean isEmpty()
	{
		return intro.isEmpty() && strategy.isEmpty();
	}

	/**
	 * Parses the plain-text extract returned by the wiki's TextExtracts API with
	 * {@code explaintext=1&exsectionformat=wiki}.
	 */
	public static WikiSummary parse(String extract)
	{
		if (extract == null || extract.trim().isEmpty())
		{
			return new WikiSummary("", "");
		}

		String text = extract.replace("\r\n", "\n");
		Matcher m = HEADING.matcher(text);

		String intro;
		StringBuilder strategy = new StringBuilder();

		int firstHeading = -1;
		int lastEnd = 0;
		String currentTitle = null;
		int currentStart = 0;
		while (m.find())
		{
			if (firstHeading < 0)
			{
				firstHeading = m.start();
			}
			else
			{
				appendSection(strategy, currentTitle, text.substring(currentStart, m.start()));
			}
			currentTitle = m.group(2);
			currentStart = m.end();
			lastEnd = m.end();
		}
		if (firstHeading < 0)
		{
			intro = text;
		}
		else
		{
			intro = text.substring(0, firstHeading);
			appendSection(strategy, currentTitle, text.substring(lastEnd));
		}

		return new WikiSummary(
			truncate(clean(intro), MAX_INTRO_CHARS),
			truncate(clean(strategy.toString()), MAX_STRATEGY_CHARS));
	}

	private static void appendSection(StringBuilder out, String title, String body)
	{
		if (title == null)
		{
			return;
		}
		if (!KEEP_SECTIONS.contains(title.trim().toLowerCase(Locale.ROOT)))
		{
			return;
		}
		String cleaned = clean(body);
		if (cleaned.isEmpty())
		{
			return;
		}
		if (out.length() > 0)
		{
			out.append("\n\n");
		}
		out.append(cleaned);
	}

	/** Collapses blank lines and surrounding whitespace. */
	static String clean(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replaceAll("[ \\t]+\\n", "\n")
			.replaceAll("\\n{3,}", "\n\n")
			.trim();
	}

	/**
	 * Cuts text to at most {@code max} characters, preferring to stop at the end of a sentence
	 * and adding an ellipsis when something was dropped.
	 */
	static String truncate(String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		if (s.length() <= max)
		{
			return s;
		}
		String head = s.substring(0, max);
		int sentence = Math.max(head.lastIndexOf(". "), head.lastIndexOf(".\n"));
		int line = head.lastIndexOf('\n');
		int cut;
		if (sentence >= max / 2)
		{
			cut = sentence + 1;
		}
		else if (line >= max / 2)
		{
			cut = line;
		}
		else
		{
			cut = head.lastIndexOf(' ');
			if (cut <= 0)
			{
				cut = max;
			}
		}
		String out = s.substring(0, cut).trim();
		if (out.endsWith("."))
		{
			return out + " …";
		}
		return out + "…";
	}
}

package com.calookup;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * A thin rounded progress bar. Used both for a task's wiki completion rate and for the
 * player's own progress through a boss or tier.
 */
class RateBar extends JComponent
{
	private double fraction;
	private Color fill;
	private Color track;
	private final int height;

	RateBar(int height, Color fill, Color track)
	{
		this.height = height;
		this.fill = fill;
		this.track = track;
		setOpaque(false);
		setPreferredSize(new Dimension(60, height));
		setMinimumSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
	}

	/** @param fraction 0..1, or negative for "unknown" (draws only the track) */
	void setFraction(double fraction)
	{
		this.fraction = fraction;
		repaint();
	}

	void setColors(Color fill, Color track)
	{
		this.fill = fill;
		this.track = track;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = Math.min(getHeight(), height);
		int y = (getHeight() - h) / 2;
		g2.setColor(track);
		g2.fillRoundRect(0, y, w, h, h, h);
		if (fraction > 0)
		{
			int fw = (int) Math.round(w * Math.min(1.0, fraction));
			fw = Math.max(fw, h);
			g2.setColor(fill);
			g2.fillRoundRect(0, y, fw, h, h, h);
		}
		g2.dispose();
	}
}

