/**
 * One task inside a tier section. Shows the done mark, the title, the type and the wiki
 * completion rate. Clicking it opens the in-game description, the wiki summary and a button
 * to open the full page.
 * <p>
 * Rows are cheap to build on purpose: the "(All)" view creates several hundred of them. The
 * detail area is only built the first time a row is expanded, the type line is plain text, and
 * the title only uses a wrapping HTML label when it is too long to fit on one line.
 */
class TaskRow extends JPanel
{
	static final int INNER_WIDTH = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET - 4;
	private static final int TEXT_WIDTH = INNER_WIDTH - 24;
	/** Room for the title once the mark (14 + gap) and the rate column (44 + gap) are taken. */
	private static final int NAME_WIDTH = INNER_WIDTH - 12 - 20 - 50 - 8;
	/** Space left below each row instead of a separate spacer component. */
	private static final int GAP = 3;

	private final CombatTask task;
	private final LookupPanel owner;
	private final MouseAdapter clicks;

	private final JPanel head = new JPanel(new BorderLayout(6, 0));
	private final StatusMark mark;
	private final JLabel name = new JLabel();
	private final JLabel type = new JLabel();
	private final RateBar rateBar;
	private final JLabel rateLabel = new JLabel("", SwingConstants.RIGHT);
	private final JLabel progressLabel = new JLabel();

	// Built lazily by ensureDetails()
	private JPanel details;
	private JLabel description;
	private JLabel wikiHeading;
	private JLabel wikiIntro;
	private JLabel wikiStrategy;
	private JLabel wikiStatus;
	private JButton openWiki;

	private Theme theme;
	private Color background;
	private String typeText = "";
	private TaskProgress progress;
	private boolean done;
	private boolean unknown;
	private boolean expanded;
	private boolean hover;

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (background != null)
		{
			g.setColor(background);
			g.fillRect(0, 0, getWidth(), getHeight() - GAP);
		}
	}

	/**
	 * @param showBoss whether to name the boss on the row, used when every boss is listed together
	 */
	TaskRow(CombatTask task, LookupPanel owner, Theme theme, boolean showBoss)
	{
		this.task = task;
		this.owner = owner;
		this.theme = theme;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		// The bottom 3 px is the gap to the next row; the background is painted above it.
		setBorder(BorderFactory.createEmptyBorder(5, 6, 5 + GAP, 6));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setOpaque(false);

		mark = new StatusMark(theme.tierColor(task.getTier()), theme.getMuted());

		// Head: mark | name + type | rate
		head.setOpaque(false);
		head.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel markWrap = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
		markWrap.setOpaque(false);
		markWrap.add(mark);
		head.add(markWrap, BorderLayout.WEST);

		JPanel middle = new JPanel();
		middle.setOpaque(false);
		middle.setLayout(new BoxLayout(middle, BoxLayout.Y_AXIS));
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		type.setFont(FontManager.getRunescapeSmallFont());
		type.setAlignmentX(Component.LEFT_ALIGNMENT);
		middle.add(name);
		middle.add(type);
		head.add(middle, BorderLayout.CENTER);

		JPanel rateWrap = new JPanel();
		rateWrap.setOpaque(false);
		rateWrap.setLayout(new BoxLayout(rateWrap, BoxLayout.Y_AXIS));
		rateLabel.setFont(FontManager.getRunescapeSmallFont());
		rateLabel.setAlignmentX(Component.RIGHT_ALIGNMENT);
		rateBar = new RateBar(5, theme.tierColor(task.getTier()), theme.getTrack());
		rateBar.setPreferredSize(new Dimension(44, 5));
		rateBar.setMaximumSize(new Dimension(44, 5));
		rateBar.setAlignmentX(Component.RIGHT_ALIGNMENT);
		rateWrap.add(rateLabel);
		rateWrap.add(Box.createVerticalStrut(2));
		rateWrap.add(rateBar);
		head.add(rateWrap, BorderLayout.EAST);

		add(head);

		// Kill count / PB line, only shown when there is something to say
		progressLabel.setFont(FontManager.getRunescapeSmallFont());
		progressLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		progressLabel.setBorder(BorderFactory.createEmptyBorder(1, 20, 0, 0));
		progressLabel.setVisible(false);
		add(progressLabel);

		clicks = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				owner.toggleExpanded(task);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				paintState();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				paintState();
			}
		};
		addMouseListener(clicks);
		head.addMouseListener(clicks);
		middle.addMouseListener(clicks);
		markWrap.addMouseListener(clicks);
		rateWrap.addMouseListener(clicks);
		name.addMouseListener(clicks);
		type.addMouseListener(clicks);
		progressLabel.addMouseListener(clicks);

		// Title: plain when it fits, wrapping HTML only when it would be cut off.
		Font nameFont = name.getFont();
		if (name.getFontMetrics(nameFont).stringWidth(task.getName()) <= NAME_WIDTH)
		{
			name.setText(task.getName());
		}
		else
		{
			name.setText(htmlNarrow(escape(task.getName())));
		}
		name.setToolTipText(task.getName());

		int points = task.getTier().getPoints();
		typeText = task.getType().getLabel() + "  ·  " + points + (points == 1 ? " pt" : " pts");
		if (showBoss)
		{
			typeText += "  ·  " + task.getBoss();
		}
		type.setText(typeText);
		type.setToolTipText(typeText);
		paintState();
	}

	/**
	 * Shows the player's own standing (kill count or PB) on a line under the row head. The line
	 * turns green once the number already meets the task's target.
	 */
	void setProgress(TaskProgress progress)
	{
		boolean same = progress == null ? this.progress == null
			: this.progress != null && progress.getText().equals(this.progress.getText()) && progress.isMet() == this.progress.isMet();
		if (same)
		{
			return;
		}
		this.progress = progress;
		if (progress == null)
		{
			progressLabel.setVisible(false);
		}
		else
		{
			progressLabel.setText(progress.getText());
			progressLabel.setToolTipText(progress.isMet() ? "Target met" : "From your kill counts and personal bests");
			progressLabel.setVisible(true);
		}
		paintState();
	}

	CombatTask getTask()
	{
		return task;
	}

	private static String html(String body)
	{
		return "<html><body style='width: " + TEXT_WIDTH + "pt'>" + body + "</body></html>";
	}

	/** Wrapping label for the title, which shares its line with the mark and the rate. */
	private static String htmlNarrow(String body)
	{
		return "<html><body style='width: " + NAME_WIDTH + "pt'>" + body + "</body></html>";
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\n", "<br>");
	}

	/** Builds the expandable area the first time it is needed. */
	private void ensureDetails()
	{
		if (details != null)
		{
			return;
		}
		details = new JPanel();
		details.setOpaque(false);
		details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
		details.setAlignmentX(Component.LEFT_ALIGNMENT);
		details.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));

		description = new JLabel(html(escape(task.getDescription())));
		description.setFont(FontManager.getRunescapeSmallFont());
		description.setAlignmentX(Component.LEFT_ALIGNMENT);
		description.addMouseListener(clicks);
		details.add(description);
		details.add(Box.createVerticalStrut(6));

		wikiHeading = new JLabel("From the wiki");
		wikiHeading.setFont(FontManager.getRunescapeBoldFont());
		wikiHeading.setAlignmentX(Component.LEFT_ALIGNMENT);
		details.add(wikiHeading);

		wikiStatus = new JLabel();
		wikiStatus.setFont(FontManager.getRunescapeSmallFont());
		wikiStatus.setAlignmentX(Component.LEFT_ALIGNMENT);
		details.add(wikiStatus);

		wikiIntro = new JLabel();
		wikiIntro.setFont(FontManager.getRunescapeSmallFont());
		wikiIntro.setAlignmentX(Component.LEFT_ALIGNMENT);
		details.add(wikiIntro);

		wikiStrategy = new JLabel();
		wikiStrategy.setFont(FontManager.getRunescapeSmallFont());
		wikiStrategy.setAlignmentX(Component.LEFT_ALIGNMENT);
		details.add(wikiStrategy);
		details.add(Box.createVerticalStrut(6));

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		buttons.setOpaque(false);
		buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
		openWiki = new JButton("Open on wiki");
		openWiki.setFont(FontManager.getRunescapeSmallFont());
		openWiki.setMargin(new Insets(2, 8, 2, 8));
		openWiki.setFocusable(false);
		openWiki.setToolTipText("Open the full task page in your browser");
		openWiki.addActionListener(e -> owner.openWiki(task));
		buttons.add(openWiki);
		details.add(buttons);
		details.add(Box.createVerticalStrut(4));

		details.setVisible(false);
		add(details);
	}

	void setTheme(Theme theme)
	{
		this.theme = theme;
		mark.setColors(theme.tierColor(task.getTier()), theme.getMuted());
		rateBar.setColors(theme.tierColor(task.getTier()), theme.getTrack());
		paintState();
	}

	void setCompletion(boolean done, boolean unknown)
	{
		if (this.done == done && this.unknown == unknown)
		{
			return;
		}
		this.done = done;
		this.unknown = unknown;
		mark.setState(done, unknown);
		paintState();
	}

	void setRate(Double rate)
	{
		if (rate == null)
		{
			rateLabel.setText("n/a");
			rateLabel.setToolTipText("The wiki has no completion rate for this task");
			rateBar.setFraction(-1);
		}
		else
		{
			rateLabel.setText(String.format(Locale.ROOT, rate >= 10 ? "%.0f%%" : "%.1f%%", rate));
			rateLabel.setToolTipText(String.format(Locale.ROOT, "%.1f%% of players have completed this task", rate));
			rateBar.setFraction(rate / 100.0);
		}
	}

	void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		if (expanded)
		{
			ensureDetails();
		}
		if (details != null)
		{
			details.setVisible(expanded);
		}
		paintState();
	}

	boolean isExpanded()
	{
		return expanded;
	}

	void showSummaryLoading()
	{
		ensureDetails();
		wikiStatus.setText(html("Fetching from the wiki…"));
		wikiStatus.setVisible(true);
		wikiIntro.setVisible(false);
		wikiStrategy.setVisible(false);
	}

	void showSummary(WikiSummary summary)
	{
		ensureDetails();
		if (summary == null || summary.isEmpty())
		{
			wikiStatus.setText(html("The wiki page has no description yet."));
			wikiStatus.setVisible(true);
			wikiIntro.setVisible(false);
			wikiStrategy.setVisible(false);
			return;
		}
		wikiStatus.setVisible(false);
		wikiIntro.setText(html(escape(summary.getIntro())));
		wikiIntro.setVisible(!summary.getIntro().isEmpty());
		if (summary.getStrategy().isEmpty())
		{
			wikiStrategy.setVisible(false);
		}
		else
		{
			wikiStrategy.setText(html("<b>Strategy</b><br>" + escape(summary.getStrategy())));
			wikiStrategy.setVisible(true);
		}
	}

	void showSummaryError(String message)
	{
		ensureDetails();
		wikiStatus.setText(html(escape(message)));
		wikiStatus.setVisible(true);
		wikiIntro.setVisible(false);
		wikiStrategy.setVisible(false);
	}

	private void paintState()
	{
		background = expanded ? theme.getCardOpen() : (hover ? theme.getCardHover() : theme.getCard());

		name.setForeground(done ? theme.getMuted() : theme.getText());
		type.setForeground(theme.getMuted());
		progressLabel.setForeground(progress != null && progress.isMet() ? theme.tierColor(TaskTier.EASY) : theme.getMuted());
		rateLabel.setForeground(done ? theme.getMuted() : theme.getText());
		if (details != null)
		{
			description.setForeground(theme.getText());
			wikiHeading.setForeground(theme.tierColor(task.getTier()));
			wikiStatus.setForeground(theme.getMuted());
			wikiIntro.setForeground(theme.getText());
			wikiStrategy.setForeground(theme.getText());
			openWiki.setBackground(theme.getCardHover());
			openWiki.setForeground(theme.getText());
		}
		setToolTipText(done ? "Completed" : (unknown ? "Log in to see whether you have completed this task" : "Not completed yet"));
		repaint();
	}
}

package com.calookup;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The player's own standing against a task's target, shown on the row: "you: 61 / 150" for
 * kill-count tasks and "under 1:20, your best 1:12" for speed tasks. Built from RuneLite's
 * Chat Commands data, which the client already keeps per character.
 */
final class TaskProgress
{
	private static final Pattern TIMES = Pattern.compile("(\\d[\\d,]*)\\s+times", Pattern.CASE_INSENSITIVE);
	private static final Pattern MIN_SEC = Pattern.compile("(\\d+)\\s*min(?:ute)?s?(?:\\s*(?:and\\s*)?(\\d+)\\s*sec(?:ond)?s?)?", Pattern.CASE_INSENSITIVE);
	private static final Pattern SCALE = Pattern.compile("\\((\\d+)-scale\\)", Pattern.CASE_INSENSITIVE);
	private static final Pattern GROUP_OF = Pattern.compile("(?:group|team) of (\\d+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern SEC_ONLY = Pattern.compile("(\\d+)\\s*seconds?", Pattern.CASE_INSENSITIVE);
	private static final Pattern CLOCK = Pattern.compile("(\\d+):(\\d\\d)(?:\\.(\\d+))?");

	private final String text;
	private final boolean met;

	TaskProgress(String text, boolean met)
	{
		this.text = text;
		this.met = met;
	}

	/** Short text appended to the row's type line. */
	String getText()
	{
		return text;
	}

	/** True when the player's number already satisfies the task's target. */
	boolean isMet()
	{
		return met;
	}

	/**
	 * @return the number of kills a kill-count task asks for, or -1 if the text has none.
	 * "once" and "twice" count; "Kill X 150 times" gives 150.
	 */
	static int parseKillTarget(String description)
	{
		if (description == null)
		{
			return -1;
		}
		Matcher m = TIMES.matcher(description);
		if (m.find())
		{
			try
			{
				return Integer.parseInt(m.group(1).replace(",", ""));
			}
			catch (NumberFormatException e)
			{
				return -1;
			}
		}
		String lower = description.toLowerCase(Locale.ROOT);
		if (lower.contains(" once"))
		{
			return 1;
		}
		if (lower.contains(" twice"))
		{
			return 2;
		}
		return -1;
	}

	/**
	 * @return the time limit of a speed task in seconds, or -1 if the text has none.
	 * Understands "1 minute 20 seconds", "54 seconds", "20 minutes" and "2:30".
	 */
	static double parseSpeedTargetSeconds(String description)
	{
		if (description == null)
		{
			return -1;
		}
		Matcher clock = CLOCK.matcher(description);
		if (clock.find())
		{
			return Integer.parseInt(clock.group(1)) * 60 + Integer.parseInt(clock.group(2));
		}
		Matcher ms = MIN_SEC.matcher(description);
		if (ms.find())
		{
			int minutes = Integer.parseInt(ms.group(1));
			int seconds = ms.group(2) == null ? 0 : Integer.parseInt(ms.group(2));
			return minutes * 60 + seconds;
		}
		Matcher s = SEC_ONLY.matcher(description);
		if (s.find())
		{
			return Integer.parseInt(s.group(1));
		}
		return -1;
	}

	/**
	 * The team size a raid task is specific to, in the spelling Chat Commands uses for its
	 * per-size personal bests: {@code solo}, {@code 2 players}, {@code 5 players}. Null when
	 * the task does not name a size ("at any group size", or not a raid), in which case the
	 * boss's overall best applies.
	 */
	static String parseTeamSize(String description)
	{
		if (description == null)
		{
			return null;
		}
		String lower = description.toLowerCase(Locale.ROOT);
		if (lower.contains("(solo)"))
		{
			return "solo";
		}
		if (lower.contains("(duo)"))
		{
			return "2 players";
		}
		if (lower.contains("(trio)"))
		{
			return "3 players";
		}
		Matcher scale = SCALE.matcher(description);
		if (scale.find())
		{
			return players(Integer.parseInt(scale.group(1)));
		}
		Matcher group = GROUP_OF.matcher(description);
		if (group.find())
		{
			return players(Integer.parseInt(group.group(1)));
		}
		return null;
	}

	private static String players(int n)
	{
		return n == 1 ? "solo" : n + " players";
	}

	/** Formats seconds as m:ss, keeping tenths when the value has them (the client stores 0.6 s ticks). */
	static String formatTime(double seconds)
	{
		int whole = (int) Math.floor(seconds);
		double frac = seconds - whole;
		int minutes = whole / 60;
		int secs = whole % 60;
		if (frac >= 0.05)
		{
			return String.format(Locale.ROOT, "%d:%02d.%d", minutes, secs, (int) Math.round(frac * 10) % 10);
		}
		return String.format(Locale.ROOT, "%d:%02d", minutes, secs);
	}

	static TaskProgress forKillCount(int have, int target)
	{
		return new TaskProgress("Your kills: " + have + " / " + target, have >= target);
	}

	static TaskProgress forSpeed(double bestSeconds, double targetSeconds)
	{
		return new TaskProgress("Under " + formatTime(targetSeconds) + "  ·  your best " + formatTime(bestSeconds),
			bestSeconds < targetSeconds);
	}
}

package com.calookup;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/**
 * A small circle: hollow while a task is still to do, filled with a tick once it is done, and
 * a dotted ring when completion is unknown because the player is logged out.
 */
class StatusMark extends JComponent
{
	private static final int SIZE = 14;

	private boolean done;
	private boolean unknown;
	private Color color;
	private Color ring;

	StatusMark(Color color, Color ring)
	{
		this.color = color;
		this.ring = ring;
		setOpaque(false);
		Dimension d = new Dimension(SIZE, SIZE);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
	}

	void setState(boolean done, boolean unknown)
	{
		this.done = done;
		this.unknown = unknown;
		repaint();
	}

	void setColors(Color color, Color ring)
	{
		this.color = color;
		this.ring = ring;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int d = SIZE - 2;
		int x = (getWidth() - d) / 2;
		int y = (getHeight() - d) / 2;
		if (done)
		{
			g2.setColor(color);
			g2.fillOval(x, y, d, d);
			g2.setColor(Color.WHITE);
			g2.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g2.drawLine(x + 3, y + d / 2, x + d / 2 - 1, y + d - 4);
			g2.drawLine(x + d / 2 - 1, y + d - 4, x + d - 3, y + 3);
		}
		else if (unknown)
		{
			g2.setColor(ring);
			g2.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{2f, 2f}, 0f));
			g2.drawOval(x, y, d, d);
		}
		else
		{
			g2.setColor(ring);
			g2.setStroke(new BasicStroke(1.4f));
			g2.drawOval(x, y, d, d);
		}
		g2.dispose();
	}
}

package com.calookup;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Reads the Combat Achievement task list out of the game cache and the player's completion
 * bits out of their varps.
 * <p>
 * Every method that touches {@link Client} must be called on the client thread. The results
 * are immutable snapshots that may then be handed to any thread.
 */
@Slf4j
class CombatTaskRepository
{
	/** Struct param: the task's numeric ID. */
	static final int PARAM_TASK_ID = 1306;
	/** Struct param: the task's title. */
	static final int PARAM_TASK_NAME = 1308;
	/** Struct param: the task's in-game description. */
	static final int PARAM_TASK_DESCRIPTION = 1309;
	/** Struct param: the task type (see {@link TaskType}). */
	static final int PARAM_TASK_TYPE = 1311;
	/** Struct param: index into the boss-name enum. */
	static final int PARAM_TASK_BOSS = 1312;
	/** Enum mapping boss index to boss display name. */
	static final int ENUM_BOSS_NAMES = 3971;

	/** Name the game uses for tasks that are not tied to a boss. */
	static final String GENERAL_BOSS = "None";

	/**
	 * Each varp holds 32 completion bits. Task {@code n} is bit {@code n % 32} of
	 * {@code COMPLETED_VARPS[n / 32]}, exactly as the game's own interface reads them.
	 */
	static final int[] COMPLETED_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1,
		VarPlayerID.CA_TASK_COMPLETED_2, VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8, VarPlayerID.CA_TASK_COMPLETED_9,
		VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
		VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
		VarPlayerID.CA_TASK_COMPLETED_20,
	};

	private static final Set<Integer> COMPLETED_VARP_SET = new HashSet<>();

	static
	{
		for (int varp : COMPLETED_VARPS)
		{
			COMPLETED_VARP_SET.add(varp);
		}
	}

	private final Client client;

	/** All tasks, in tier order then cache order. Replaced wholesale, never mutated. */
	private volatile List<CombatTask> tasks = Collections.emptyList();

	/** Tasks grouped by normalised boss name. */
	private volatile Map<String, List<CombatTask>> byBoss = Collections.emptyMap();

	/** Display names of every boss group, sorted alphabetically. */
	private volatile List<String> bossNames = Collections.emptyList();

	CombatTaskRepository(Client client)
	{
		this.client = client;
	}

	/** @return true if the given varp is one of the Combat Achievement completion varps */
	static boolean isCompletionVarp(int varpId)
	{
		return COMPLETED_VARP_SET.contains(varpId);
	}

	boolean isLoaded()
	{
		return !tasks.isEmpty();
	}

	List<CombatTask> getTasks()
	{
		return tasks;
	}

	List<String> getBossNames()
	{
		return bossNames;
	}

	/**
	 * @param boss a boss display name, in any capitalisation
	 * @return the tasks filed under that boss, or an empty list
	 */
	List<CombatTask> tasksFor(String boss)
	{
		List<CombatTask> list = byBoss.get(BossMatcher.normalize(boss));
		return list == null ? Collections.emptyList() : list;
	}

	/** @return the display name of the boss group matching the given name, or null */
	String resolveBoss(String boss)
	{
		String key = BossMatcher.normalize(boss);
		List<CombatTask> list = byBoss.get(key);
		if (list == null || list.isEmpty())
		{
			return null;
		}
		return list.get(0).getBoss();
	}

	/**
	 * Reads every task struct out of the cache. Must run on the client thread.
	 *
	 * @return true if at least one task was loaded
	 */
	boolean load()
	{
		List<CombatTask> loaded = new ArrayList<>();
		EnumComposition bossEnum = client.getEnum(ENUM_BOSS_NAMES);

		for (TaskTier tier : TaskTier.values())
		{
			EnumComposition tierEnum = client.getEnum(tier.getEnumId());
			if (tierEnum == null)
			{
				log.debug("No enum {} for tier {}", tier.getEnumId(), tier);
				continue;
			}
			for (int structId : tierEnum.getIntVals())
			{
				StructComposition struct = client.getStructComposition(structId);
				if (struct == null)
				{
					continue;
				}
				int id = struct.getIntValue(PARAM_TASK_ID);
				String name = struct.getStringValue(PARAM_TASK_NAME);
				String description = struct.getStringValue(PARAM_TASK_DESCRIPTION);
				TaskType type = TaskType.fromId(struct.getIntValue(PARAM_TASK_TYPE));
				int bossIndex = struct.getIntValue(PARAM_TASK_BOSS);
				String boss = bossEnum == null ? null : bossEnum.getStringValue(bossIndex);
				if (boss == null || boss.isEmpty())
				{
					boss = GENERAL_BOSS;
				}
				loaded.add(new CombatTask(id, name, description, tier, type, boss));
			}
		}

		if (loaded.isEmpty())
		{
			return false;
		}

		Map<String, List<CombatTask>> grouped = new LinkedHashMap<>();
		Set<String> names = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (CombatTask task : loaded)
		{
			grouped.computeIfAbsent(BossMatcher.normalize(task.getBoss()), k -> new ArrayList<>()).add(task);
			names.add(task.getBoss());
		}
		for (Map.Entry<String, List<CombatTask>> entry : grouped.entrySet())
		{
			entry.setValue(Collections.unmodifiableList(entry.getValue()));
		}

		tasks = Collections.unmodifiableList(loaded);
		byBoss = Collections.unmodifiableMap(grouped);
		bossNames = Collections.unmodifiableList(new ArrayList<>(names));
		log.debug("Loaded {} combat achievement tasks across {} bosses", loaded.size(), names.size());
		return true;
	}

	/**
	 * Reads the completion bit of every task. Must run on the client thread.
	 *
	 * @return the IDs of every completed task
	 */
	Set<Integer> readCompleted()
	{
		int[] values = new int[COMPLETED_VARPS.length];
		for (int i = 0; i < COMPLETED_VARPS.length; i++)
		{
			values[i] = client.getVarpValue(COMPLETED_VARPS[i]);
		}

		Set<Integer> completed = new HashSet<>();
		for (CombatTask task : tasks)
		{
			if (isCompleted(values, task.getId()))
			{
				completed.add(task.getId());
			}
		}
		return Collections.unmodifiableSet(completed);
	}

	/**
	 * Varbits holding the points needed for each tier's rewards, Easy to Grandmaster. The same
	 * values the in-game interface shows; read from the client rather than hard-coded so a
	 * rebalance needs no plugin update.
	 */
	static final int[] THRESHOLD_VARBITS = {4132, 10660, 10661, 14812, 14813, 14814};

	/** Total points earned from the given completed tasks. */
	int pointsEarned(Set<Integer> completed)
	{
		int points = 0;
		for (CombatTask task : tasks)
		{
			if (completed.contains(task.getId()))
			{
				points += task.getTier().getPoints();
			}
		}
		return points;
	}

	/**
	 * "312 points · 8 more for Hard", or null when the thresholds are not available.
	 * Must run on the client thread.
	 */
	String pointsLine(Set<Integer> completed)
	{
		int[] thresholds = new int[THRESHOLD_VARBITS.length];
		for (int i = 0; i < thresholds.length; i++)
		{
			thresholds[i] = client.getVarbitValue(THRESHOLD_VARBITS[i]);
			if (thresholds[i] <= 0)
			{
				return null;
			}
		}
		return pointsLine(pointsEarned(completed), thresholds);
	}

	/** Pure formatting, split out so it can be unit tested without a client. */
	static String pointsLine(int points, int[] thresholds)
	{
		TaskTier[] tiers = TaskTier.values();
		for (int i = 0; i < thresholds.length && i < tiers.length; i++)
		{
			if (points < thresholds[i])
			{
				int more = thresholds[i] - points;
				return points + (points == 1 ? " point" : " points") + "  ·  " + more + " more for " + tiers[i].getDisplayName();
			}
		}
		return points + " points  ·  Grandmaster reached";
	}

	/** Pure bit test, split out so it can be unit tested without a client. */
	static boolean isCompleted(int[] varpValues, int taskId)
	{
		if (taskId < 0)
		{
			return false;
		}
		int index = taskId / 32;
		if (index >= varpValues.length)
		{
			return false;
		}
		return (varpValues[index] & (1 << (taskId % 32))) != 0;
	}

	void clear()
	{
		tasks = Collections.emptyList();
		byBoss = Collections.emptyMap();
		bossNames = Collections.emptyList();
	}
}

package com.calookup;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.BoxLayout;
import javax.swing.JPanel;

/**
 * The header block behind the crest, title and summary. When a boss portrait is available it
 * is painted at the right edge, fading into the background towards the text so the header
 * reads like a bestiary page without hurting legibility.
 */
class PortraitHeader extends JPanel
{
	/** Portrait height in pixels; the width follows the image's aspect ratio. */
	static final int PORTRAIT_HEIGHT = 64;
	private static final float PORTRAIT_ALPHA = 0.9f;

	private BufferedImage portrait;
	private Color background = Color.BLACK;

	PortraitHeader()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
	}

	void setPortrait(BufferedImage portrait)
	{
		this.portrait = portrait;
		repaint();
	}

	void setBackgroundColor(Color background)
	{
		this.background = background;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (portrait == null)
		{
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);

		int h = Math.min(PORTRAIT_HEIGHT, getHeight());
		int w = Math.max(1, (int) Math.round(portrait.getWidth() * (h / (double) portrait.getHeight())));
		int x = getWidth() - w;
		int y = 0;

		g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, PORTRAIT_ALPHA));
		g2.drawImage(portrait, x, y, w, h, null);

		// Fade the left half of the portrait into the background so text stays readable.
		g2.setComposite(AlphaComposite.SrcOver);
		Color solid = background;
		Color clear = new Color(background.getRed(), background.getGreen(), background.getBlue(), 0);
		g2.setPaint(new GradientPaint(x, 0, solid, x + w * 0.6f, 0, clear));
		g2.fillRect(x, y, w, h);
		g2.dispose();
	}
}

package com.calookup;

import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import javax.swing.ComboBoxEditor;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JComboBox;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

/**
 * A combo box you can type into. The list narrows to entries containing the typed text as you
 * type, arrow keys and the mouse pick from the narrowed list, and Enter picks the first match.
 */
class SearchableComboBox extends JComboBox<String>
{
	private List<String> all = Collections.emptyList();
	private final JTextField editorField;
	private Consumer<String> onSelect = s ->
	{
	};

	/** Set while the model or editor text is being changed by code, so listeners stay quiet. */
	private boolean updating;
	/** The last item chosen through this box, so re-selecting it does not fire again. */
	private String current;

	SearchableComboBox()
	{
		setEditable(true);
		editorField = (JTextField) getEditor().getEditorComponent();

		editorField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				typed();
			}
		});

		editorField.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusGained(FocusEvent e)
			{
				// Make the whole name replaceable in one keystroke.
				SwingUtilities.invokeLater(editorField::selectAll);
			}

			@Override
			public void focusLost(FocusEvent e)
			{
				// Put the chosen boss back if the user wandered off mid-search.
				if (!updating)
				{
					setText(current == null ? "" : current);
					resetModel();
				}
			}
		});

		// A click places a caret, which would undo the select-all above and leave the user
		// editing the middle of a boss name. Re-select everything so typing replaces it.
		editorField.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (editorField.getSelectedText() == null || editorField.getSelectedText().length() < editorField.getText().length())
				{
					SwingUtilities.invokeLater(editorField::selectAll);
				}
			}
		});

		addActionListener(e ->
		{
			if (updating)
			{
				return;
			}
			Object selected = getSelectedItem();
			String match = selected instanceof String ? resolve((String) selected) : null;
			if (match == null)
			{
				return;
			}
			String previous = current;
			current = match;
			setText(match);
			resetModel();
			if (!match.equals(previous))
			{
				onSelect.accept(match);
			}
		});
	}

	/** Called when the user picks an entry, with the exact entry text. */
	void setOnSelect(Consumer<String> onSelect)
	{
		this.onSelect = onSelect;
	}

	/** Replaces the full list of entries. Keeps the current choice if it still exists. */
	void setItems(List<String> items)
	{
		all = new ArrayList<>(items);
		resetModel();
		if (current != null && !all.contains(current))
		{
			current = null;
			setText("");
		}
	}

	/** Shows an entry as chosen without firing {@link #setOnSelect}. */
	void setCurrent(String item)
	{
		current = item;
		setText(item == null ? "" : item);
		resetModel();
	}

	@Override
	public void configureEditor(ComboBoxEditor anEditor, Object anItem)
	{
		// Selection changes (arrow keys, mouse) rewrite the editor text; do not treat that as typing.
		boolean was = updating;
		updating = true;
		try
		{
			super.configureEditor(anEditor, anItem);
			// Called from the JComboBox constructor too, before editorField is assigned.
			if (editorField != null && !editorField.hasFocus())
			{
				editorField.setCaretPosition(0);
			}
		}
		finally
		{
			updating = was;
		}
	}

	private void typed()
	{
		if (updating)
		{
			return;
		}
		SwingUtilities.invokeLater(this::filter);
	}

	private void filter()
	{
		if (updating)
		{
			return;
		}
		String text = editorField.getText();
		List<String> matches = matching(all, text);
		updating = true;
		try
		{
			setModel(new DefaultComboBoxModel<>(matches.toArray(new String[0])));
			setSelectedItem(null);
			editorField.setText(text);
			if (isShowing() && editorField.hasFocus())
			{
				// Re-open so the popup resizes to the narrowed list.
				setPopupVisible(false);
				if (!matches.isEmpty())
				{
					setPopupVisible(true);
				}
			}
		}
		finally
		{
			updating = false;
		}
	}

	private void resetModel()
	{
		updating = true;
		try
		{
			setModel(new DefaultComboBoxModel<>(all.toArray(new String[0])));
			setSelectedItem(current);
			setText(current == null ? "" : current);
		}
		finally
		{
			updating = false;
		}
	}

	private void setText(String text)
	{
		boolean was = updating;
		updating = true;
		try
		{
			editorField.setText(text);
			// Show the start of long names ("Tombs of Amascut: ..."), not the tail.
			editorField.setCaretPosition(0);
		}
		finally
		{
			updating = was;
		}
	}

	/** Turns typed text into an entry: exact match first, then the first containing match. */
	private String resolve(String text)
	{
		if (text == null)
		{
			return null;
		}
		String trimmed = text.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}
		for (String item : all)
		{
			if (item.equalsIgnoreCase(trimmed))
			{
				return item;
			}
		}
		List<String> matches = matching(all, trimmed);
		return matches.isEmpty() ? null : matches.get(0);
	}

	/** Entries containing the text, case-insensitive; the whole list for empty text. */
	static List<String> matching(List<String> items, String text)
	{
		String needle = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
		if (needle.isEmpty())
		{
			return new ArrayList<>(items);
		}
		List<String> starts = new ArrayList<>();
		List<String> contains = new ArrayList<>();
		for (String item : items)
		{
			String hay = item.toLowerCase(Locale.ROOT);
			if (hay.startsWith(needle))
			{
				starts.add(item);
			}
			else if (hay.contains(needle))
			{
				contains.add(item);
			}
		}
		starts.addAll(contains);
		return starts;
	}
}

package com.calookup;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Everything the panel needs to show one boss: an immutable snapshot built on the client
 * thread and handed to the Swing thread.
 */
final class LookupView
{
	private final String boss;
	private final List<String> alternatives;
	private final List<CombatTask> tasks;
	private final Set<Integer> completed;
	private final boolean loggedIn;
	private final Map<Integer, TaskProgress> progress;
	private final String pointsLine;

	LookupView(String boss, List<String> alternatives, List<CombatTask> tasks, Set<Integer> completed, boolean loggedIn)
	{
		this(boss, alternatives, tasks, completed, loggedIn, Collections.emptyMap(), null);
	}

	LookupView(String boss, List<String> alternatives, List<CombatTask> tasks, Set<Integer> completed, boolean loggedIn,
		Map<Integer, TaskProgress> progress, String pointsLine)
	{
		this.boss = boss;
		this.alternatives = alternatives == null ? Collections.emptyList() : Collections.unmodifiableList(alternatives);
		this.tasks = Collections.unmodifiableList(tasks);
		this.completed = Collections.unmodifiableSet(completed);
		this.loggedIn = loggedIn;
		this.progress = progress == null ? Collections.emptyMap() : Collections.unmodifiableMap(progress);
		this.pointsLine = pointsLine;
	}

	/** Display name of the boss group being shown. */
	String getBoss()
	{
		return boss;
	}

	/**
	 * Other boss groups the same NPC belongs to (for example a raid's normal and challenge
	 * modes), including {@link #getBoss()} itself. Empty when there is only one.
	 */
	List<String> getAlternatives()
	{
		return alternatives;
	}

	List<CombatTask> getTasks()
	{
		return tasks;
	}

	Set<Integer> getCompleted()
	{
		return completed;
	}

	/** False when the player is logged out, in which case completion is unknown. */
	boolean isLoggedIn()
	{
		return loggedIn;
	}

	/** Kill-count and PB standing per task, where known. */
	Map<Integer, TaskProgress> getProgress()
	{
		return progress;
	}

	/** "312 points · 8 more for Hard", or null when unknown. */
	String getPointsLine()
	{
		return pointsLine;
	}

	LookupView withCompletion(Set<Integer> newCompleted, boolean newLoggedIn, Map<Integer, TaskProgress> newProgress,
		String newPointsLine)
	{
		return new LookupView(boss, alternatives, tasks, newCompleted, newLoggedIn, newProgress, newPointsLine);
	}
}

