/**
 * Combat Achievement Lookup: right-click a boss or monster, choose "CA Lookup", and see its
 * Combat Achievements grouped by tier with the wiki's completion rate for each task, your own
 * progress read from the game, and a short wiki guide for any task you click.
 * <p>
 * The plugin only ever reads: the task list from the game cache, your completion bits from
 * your varps, and two public read-only wiki endpoints. It adds one right-click option and
 * never changes or removes existing menu entries, sends input, or automates anything.
 */
@Slf4j
@PluginDescriptor(
	name = "CA Lookup",
	description = "Right-click a boss for CA Lookup: its Combat Achievements by tier, wiki completion rates, your progress and quick wiki guides",
	tags = {"combat", "achievements", "achievement", "ca", "cas", "tasks", "boss", "bosses", "pvm", "wiki", "lookup", "guide", "tier", "progress"}
)
public class CombatAchievementLookupPlugin extends Plugin
{
	/** Game message sent when a task is completed; used as a second trigger to refresh. */
	private static final String COMPLETION_MESSAGE = "Congratulations, you've completed";

	/** Live wiki completion rates older than this are fetched again on the next login. */
	private static final Duration RATES_MAX_AGE = Duration.ofHours(12);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CombatAchievementLookupConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private WikiClient wikiClient;

	@Inject
	private Gson gson;

	private CombatTaskRepository repository;
	private LookupPanel panel;
	private NavigationButton navButton;

	private volatile CompletionRates rates = CompletionRates.EMPTY;
	private volatile boolean ratesRequested;

	/** Set by events on the client thread; consumed on the next game tick so bursts coalesce. */
	private boolean completionDirty;

	/** The boss currently shown and the alternatives offered with it, for chip switching. */
	private volatile List<String> currentAlternatives = Collections.emptyList();

	private final Map<Integer, WikiSummary> summaryCache = new ConcurrentHashMap<>();
	private final Map<String, BufferedImage> portraitCache = new ConcurrentHashMap<>();
	private final Set<String> portraitsRequested = ConcurrentHashMap.newKeySet();
	private ProgressReader progressReader;

	@Inject
	private ConfigManager configManager;

	@Override
	protected void startUp()
	{
		repository = new CombatTaskRepository(client);
		progressReader = new ProgressReader(configManager);
		rates = CompletionRates.loadSnapshot(gson);

		panel = new LookupPanel(this, config.theme(), config.defaultFilter(), config.defaultSort(),
			config.collapseCompletedTiers());
		panel.updateRates(rates);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("CA Lookup")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invoke(() ->
		{
			ensureLoaded();
			refreshCompletion();
		});

		if (config.useWiki())
		{
			fetchRates();
		}
		log.debug("Combat Achievement Lookup started");
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		navButton = null;
		panel = null;
		if (repository != null)
		{
			repository.clear();
		}
		summaryCache.clear();
		portraitCache.clear();
		portraitsRequested.clear();
		currentAlternatives = Collections.emptyList();
		ratesRequested = false;
		log.debug("Combat Achievement Lookup stopped");
	}

	@Provides
	CombatAchievementLookupConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CombatAchievementLookupConfig.class);
	}

	// ---- Events (client thread) ----

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			// Completion is per character and is re-read from the client on every login, so
			// switching accounts just works. The wiki's global rates are refreshed if stale.
			clientThread.invokeLater(() ->
			{
				ensureLoaded();
				refreshCompletion();
			});
			if (config.useWiki() && ratesStale())
			{
				ratesRequested = false;
				fetchRates();
			}
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// No game ticks arrive while logged out, so refresh straight away.
			completionDirty = false;
			refreshCompletion();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (CombatTaskRepository.isCompletionVarp(event.getVarpId()))
		{
			completionDirty = true;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE && event.getMessage().contains(COMPLETION_MESSAGE))
		{
			completionDirty = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (completionDirty)
		{
			completionDirty = false;
			refreshCompletion();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CombatAchievementLookupConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		final Theme theme = config.theme();
		final TaskArranger.Filter filter = config.defaultFilter();
		final TaskArranger.SortMode sort = config.defaultSort();
		final boolean collapse = config.collapseCompletedTiers();
		final boolean useWiki = config.useWiki();
		SwingUtilities.invokeLater(() ->
		{
			if (panel == null)
			{
				return;
			}
			switch (event.getKey())
			{
				case CombatAchievementLookupConfig.KEY_THEME:
					panel.applyTheme(theme);
					break;
				case "defaultFilter":
				case "defaultSort":
					panel.setDefaults(filter, sort);
					break;
				case "collapseCompletedTiers":
					panel.setAutoCollapseFinished(collapse);
					break;
				default:
					break;
			}
		});
		if (CombatAchievementLookupConfig.KEY_USE_WIKI.equals(event.getKey()))
		{
			if (useWiki)
			{
				fetchRates();
			}
			else
			{
				rates = CompletionRates.loadSnapshot(gson);
				ratesRequested = false;
				final CompletionRates snapshot = rates;
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.updateRates(snapshot);
					}
				});
			}
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.addMenuOption() || event.getType() != MenuAction.EXAMINE_NPC.getId())
		{
			return;
		}
		if (config.shiftOnly() && !client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}
		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null)
		{
			return;
		}
		final String npcName = npc.getName();
		if (npcName == null || !hasTasks(npcName))
		{
			return;
		}

		// Inserting at the end while the Examine entry is being added places the option just
		// above Examine, well away from the left-click action.
		String option = config.menuOption().trim();
		if (option.isEmpty())
		{
			option = "CA Lookup";
		}
		client.getMenu().createMenuEntry(-1)
			.setOption(option)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.setIdentifier(event.getIdentifier())
			.setParam0(event.getActionParam0())
			.setParam1(event.getActionParam1())
			.onClick(e -> lookupNpc(npcName));
	}

	// ---- Lookups ----

	/** @return whether any Combat Achievement group matches this NPC name */
	boolean hasTasks(String npcName)
	{
		List<String> groups = BossMatcher.groupsFor(npcName);
		if (!repository.isLoaded())
		{
			// Cache not read yet: trust the alias table so the option is not missing early on.
			return !BossMatcher.aliasesFor(npcName).isEmpty();
		}
		for (String group : groups)
		{
			if (!repository.tasksFor(group).isEmpty())
			{
				return true;
			}
		}
		return false;
	}

	/** Opens the lookup for the boss group(s) an NPC belongs to. Safe to call from any thread. */
	void lookupNpc(String npcName)
	{
		clientThread.invoke(() ->
		{
			ensureLoaded();
			List<String> matches = new ArrayList<>();
			for (String group : BossMatcher.groupsFor(npcName))
			{
				String display = repository.resolveBoss(group);
				if (display != null && !matches.contains(display))
				{
					matches.add(display);
				}
			}
			if (matches.isEmpty())
			{
				showMessage("No Combat Achievements found for " + npcName + ".");
				return;
			}
			currentAlternatives = Collections.unmodifiableList(matches);
			showBoss(matches.get(0), matches);
		});
	}

	/** Opens the lookup for a boss group chosen in the panel. Safe to call from any thread. */
	void lookupBoss(String boss)
	{
		clientThread.invoke(() ->
		{
			ensureLoaded();
			if (BossOption.isAll(boss))
			{
				currentAlternatives = Collections.singletonList(BossOption.ALL);
				showBoss(BossOption.ALL, currentAlternatives);
				return;
			}
			String display = repository.resolveBoss(boss);
			if (display == null)
			{
				showMessage("No Combat Achievements found for " + boss + ".");
				return;
			}
			List<String> alternatives = currentAlternatives;
			boolean amongAlternatives = false;
			for (String alt : alternatives)
			{
				if (alt.equals(display))
				{
					amongAlternatives = true;
					break;
				}
			}
			if (!amongAlternatives)
			{
				alternatives = Collections.singletonList(display);
				currentAlternatives = alternatives;
			}
			showBoss(display, alternatives);
		});
	}

	/** Must run on the client thread. */
	private void showBoss(String boss, List<String> alternatives)
	{
		List<CombatTask> tasks = BossOption.isAll(boss) ? repository.getTasks() : repository.tasksFor(boss);
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Set<Integer> completed = loggedIn ? repository.readCompleted() : Collections.emptySet();
		Map<Integer, TaskProgress> progress = loggedIn ? progressReader.read(tasks) : Collections.emptyMap();
		String pointsLine = loggedIn ? repository.pointsLine(completed) : null;
		final LookupView view = new LookupView(boss, alternatives, tasks, completed, loggedIn, progress, pointsLine);
		final boolean open = config.openPanel();
		SwingUtilities.invokeLater(() ->
		{
			if (panel == null)
			{
				return;
			}
			panel.showLookup(view);
			if (open && navButton != null)
			{
				clientToolbar.openPanel(navButton);
			}
		});
		if (config.useWiki() && !BossOption.isAll(boss))
		{
			fetchPortrait(boss);
		}
	}

	/** Shows the boss's wiki image in the header, from cache when possible. */
	private void fetchPortrait(String boss)
	{
		BufferedImage cached = portraitCache.get(boss);
		if (cached != null)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.setPortrait(boss, cached);
				}
			});
			return;
		}
		if (!portraitsRequested.add(boss))
		{
			return;
		}
		wikiClient.fetchPortrait(boss, LookupPanel.PORTRAIT_SIZE,
			image ->
			{
				portraitCache.put(boss, image);
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setPortrait(boss, image);
					}
				});
			},
			error ->
			{
				log.debug("No portrait for {}: {}", boss, error);
				portraitsRequested.remove(boss);
			});
	}

	private void showMessage(String message)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.showMessage(message);
			}
		});
	}

	/** Reads the task list from the cache if that has not happened yet. Client thread only. */
	private void ensureLoaded()
	{
		if (repository.isLoaded())
		{
			return;
		}
		try
		{
			if (repository.load())
			{
				refreshCompletion();
			}
		}
		catch (RuntimeException e)
		{
			// The cache may not be readable yet; a later login or lookup retries.
			log.debug("Combat achievement task list not available yet", e);
		}
	}

	/** Re-reads completion bits and pushes them to the panel. Client thread only. */
	private void refreshCompletion()
	{
		if (!repository.isLoaded())
		{
			return;
		}
		final boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		final Set<Integer> completed = loggedIn ? repository.readCompleted() : Collections.emptySet();
		final List<BossOption> options = bossOptions(completed, loggedIn);
		final Map<Integer, TaskProgress> progress = loggedIn ? progressReader.read(repository.getTasks()) : Collections.emptyMap();
		final String pointsLine = loggedIn ? repository.pointsLine(completed) : null;
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setBossOptions(options);
				panel.updateCompletion(completed, loggedIn, progress, pointsLine);
			}
		});
	}

	/** Drop-down entries ordered by points still available. Client thread only. */
	private List<BossOption> bossOptions(Set<Integer> completed, boolean loggedIn)
	{
		List<String> bosses = repository.getBossNames();
		List<List<CombatTask>> tasksOf = new ArrayList<>(bosses.size());
		for (String boss : bosses)
		{
			tasksOf.add(repository.tasksFor(boss));
		}
		return BossOption.build(bosses, tasksOf, repository.getTasks(), completed, loggedIn);
	}

	// ---- Wiki ----

	/** @return true when the live wiki rates were never fetched or are older than {@link #RATES_MAX_AGE} */
	private boolean ratesStale()
	{
		CompletionRates current = rates;
		return current.getSource() != CompletionRates.Source.WIKI
			|| current.getFetchedAt() == null
			|| Duration.between(current.getFetchedAt(), Instant.now()).compareTo(RATES_MAX_AGE) > 0;
	}

	private void fetchRates()
	{
		if (ratesRequested)
		{
			return;
		}
		ratesRequested = true;
		wikiClient.fetchCompletionRates(
			(map, dataDate) ->
			{
				rates = CompletionRates.fromWiki(map, dataDate);
				final CompletionRates live = rates;
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.updateRates(live);
					}
				});
			},
			error ->
			{
				ratesRequested = false;
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setRatesNotice(error);
					}
				});
			});
	}

	/** Called by the panel when a task is expanded. Answers through the panel. */
	void requestSummary(CombatTask task)
	{
		final int id = task.getId();
		WikiSummary cached = summaryCache.get(id);
		if (cached != null)
		{
			panel.showSummary(id, cached);
			return;
		}
		if (!config.useWiki())
		{
			panel.showSummaryError(id, "Wiki fetching is turned off in the plugin settings. Use 'Open on wiki' instead.");
			return;
		}
		wikiClient.fetchTaskSummary(task.getName(),
			summary ->
			{
				summaryCache.put(id, summary);
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.showSummary(id, summary);
					}
				});
			},
			error -> SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.showSummaryError(id, error);
				}
			}));
	}

	void openWiki(CombatTask task)
	{
		LinkBrowser.browse(WikiClient.taskPageUrl(task.getName()).toString());
	}
}

package com.calookup;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonIOException;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.StringReader;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The plugin's only network access: read-only calls to the Old School RuneScape Wiki.
 * <ul>
 *   <li>The global completion rate of every task, one JSON page the wiki maintains, together
 *       with the timestamp of the revision so the panel can say how old the numbers are.</li>
 *   <li>The plain-text extract of one task's page, fetched when the player opens that task.</li>
 *   <li>The lead image of a boss's page, for the portrait in the panel header.</li>
 * </ul>
 * Requests use RuneLite's shared {@link OkHttpClient} and run asynchronously. Callbacks are
 * invoked on an OkHttp thread; callers must hop to the Swing thread themselves.
 */
@Slf4j
@Singleton
class WikiClient
{
	static final String WIKI_HOST = "oldschool.runescape.wiki";
	static final String USER_AGENT = "Combat Achievement Lookup RuneLite plugin (https://github.com/jimmyununu/combat-achievement-lookup)";
	static final String COMPLETION_PAGE = "Module:Combat Achievements/completion.json";

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	@Inject
	WikiClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	private static HttpUrl.Builder api()
	{
		return new HttpUrl.Builder()
			.scheme("https")
			.host(WIKI_HOST)
			.addPathSegment("api.php")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2");
	}

	/** @return the wiki page for a task, e.g. {@code https://oldschool.runescape.wiki/w/Noxious_Foe} */
	static HttpUrl taskPageUrl(String taskName)
	{
		return new HttpUrl.Builder()
			.scheme("https")
			.host(WIKI_HOST)
			.addPathSegment("w")
			.addPathSegment(taskName.replace(' ', '_'))
			.addQueryParameter("utm_source", "runelite-ca-lookup")
			.build();
	}

	/** Completion data plus the timestamp of its latest revision, in one request. */
	static HttpUrl completionUrl()
	{
		return api()
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "revisions")
			.addQueryParameter("rvprop", "timestamp|content")
			.addQueryParameter("rvslots", "main")
			.addQueryParameter("titles", COMPLETION_PAGE)
			.build();
	}

	static HttpUrl extractUrl(String taskName)
	{
		return api()
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "extracts")
			.addQueryParameter("explaintext", "1")
			.addQueryParameter("exsectionformat", "wiki")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("titles", taskName)
			.build();
	}

	static HttpUrl pageImageUrl(String title, int size)
	{
		return api()
			.addQueryParameter("action", "query")
			.addQueryParameter("prop", "pageimages")
			.addQueryParameter("pithumbsize", Integer.toString(size))
			.addQueryParameter("redirects", "1")
			.addQueryParameter("titles", title)
			.build();
	}

	private Request request(HttpUrl url)
	{
		return new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.get()
			.build();
	}

	/**
	 * Fetches the wiki's completion rate for every task.
	 *
	 * @param onSuccess receives a map of task ID to percentage, and the revision timestamp (may be null)
	 * @param onError   receives a short human-readable reason
	 */
	void fetchCompletionRates(BiConsumer<Map<Integer, Double>, Instant> onSuccess, Consumer<String> onError)
	{
		okHttpClient.newCall(request(completionUrl())).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Completion rate request failed", e);
				onError.accept("Could not reach the wiki");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						onError.accept("Wiki answered with HTTP " + response.code());
						return;
					}
					JsonObject revision = latestRevision(gson, body.string());
					if (revision == null)
					{
						onError.accept("Wiki completion data was empty");
						return;
					}
					String content = revision.getAsJsonObject("slots").getAsJsonObject("main").get("content").getAsString();
					Map<Integer, Double> rates = parseRates(gson, new StringReader(content));
					if (rates.isEmpty())
					{
						onError.accept("Wiki completion data was empty");
						return;
					}
					onSuccess.accept(rates, parseTimestamp(revision));
				}
				catch (IOException | JsonSyntaxException | JsonIOException | IllegalStateException | NullPointerException e)
				{
					log.debug("Completion rate response could not be read", e);
					onError.accept("Wiki completion data could not be read");
				}
			}
		});
	}

	/** @return the first page's latest revision object, or null. Package-private for tests. */
	static JsonObject latestRevision(Gson gson, String json)
	{
		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null || !root.has("query"))
		{
			return null;
		}
		JsonElement pages = root.getAsJsonObject("query").get("pages");
		if (pages == null || !pages.isJsonArray() || pages.getAsJsonArray().size() == 0)
		{
			return null;
		}
		JsonObject page = pages.getAsJsonArray().get(0).getAsJsonObject();
		JsonElement revisions = page.get("revisions");
		if (revisions == null || !revisions.isJsonArray() || revisions.getAsJsonArray().size() == 0)
		{
			return null;
		}
		return revisions.getAsJsonArray().get(0).getAsJsonObject();
	}

	static Instant parseTimestamp(JsonObject revision)
	{
		JsonElement ts = revision.get("timestamp");
		if (ts == null || ts.isJsonNull())
		{
			return null;
		}
		try
		{
			return Instant.parse(ts.getAsString());
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	/** Parses the {@code {"0": 69.9, "1": 31.3, ...}} document. Package-private for tests. */
	static Map<Integer, Double> parseRates(Gson gson, java.io.Reader reader)
	{
		JsonObject raw = gson.fromJson(reader, JsonObject.class);
		Map<Integer, Double> rates = new HashMap<>();
		if (raw == null)
		{
			return rates;
		}
		for (Map.Entry<String, JsonElement> entry : raw.entrySet())
		{
			JsonElement value = entry.getValue();
			if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
			{
				continue;
			}
			try
			{
				rates.put(Integer.parseInt(entry.getKey().trim()), value.getAsDouble());
			}
			catch (NumberFormatException ignored)
			{
				// Not a task id; skip.
			}
		}
		return rates;
	}

	/**
	 * Fetches the plain-text extract of a task's wiki page.
	 *
	 * @param taskName  the task title, which is also its wiki page title
	 * @param onSuccess receives the parsed summary
	 * @param onError   receives a short human-readable reason
	 */
	void fetchTaskSummary(String taskName, Consumer<WikiSummary> onSuccess, Consumer<String> onError)
	{
		okHttpClient.newCall(request(extractUrl(taskName))).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Extract request failed for {}", taskName, e);
				onError.accept("Could not reach the wiki");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						onError.accept("Wiki answered with HTTP " + response.code());
						return;
					}
					String extract = parseExtract(gson, body.string());
					if (extract == null)
					{
						onError.accept("The wiki has no page for this task yet");
						return;
					}
					onSuccess.accept(WikiSummary.parse(extract));
				}
				catch (IOException | JsonSyntaxException | IllegalStateException e)
				{
					log.debug("Extract response could not be read for {}", taskName, e);
					onError.accept("Wiki page could not be read");
				}
			}
		});
	}

	/**
	 * Pulls the extract text out of a TextExtracts response, or null if the page is missing.
	 * Package-private for tests.
	 */
	static String parseExtract(Gson gson, String json)
	{
		JsonObject page = firstPage(gson, json);
		if (page == null || (page.has("missing") && page.get("missing").getAsBoolean()))
		{
			return null;
		}
		JsonElement extract = page.get("extract");
		return extract == null || extract.isJsonNull() ? "" : extract.getAsString();
	}

	/** @return the thumbnail URL from a pageimages response, or null. Package-private for tests. */
	static String parseThumbnail(Gson gson, String json)
	{
		JsonObject page = firstPage(gson, json);
		if (page == null || !page.has("thumbnail"))
		{
			return null;
		}
		JsonElement source = page.getAsJsonObject("thumbnail").get("source");
		return source == null || source.isJsonNull() ? null : source.getAsString();
	}

	private static JsonObject firstPage(Gson gson, String json)
	{
		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null || !root.has("query"))
		{
			return null;
		}
		JsonElement pagesEl = root.getAsJsonObject("query").get("pages");
		if (pagesEl == null || !pagesEl.isJsonArray())
		{
			return null;
		}
		JsonArray pages = pagesEl.getAsJsonArray();
		return pages.size() == 0 ? null : pages.get(0).getAsJsonObject();
	}

	/**
	 * Fetches the lead image of a boss's wiki page. A mode page without an image of its own
	 * (for example "Theatre of Blood: Hard Mode") falls back to its parent page.
	 *
	 * @param boss      the boss group name as the game files it
	 * @param size      thumbnail width in pixels
	 * @param onSuccess receives the decoded image
	 * @param onError   receives a short human-readable reason
	 */
	void fetchPortrait(String boss, int size, Consumer<BufferedImage> onSuccess, Consumer<String> onError)
	{
		fetchThumbnailUrl(boss, size, url ->
		{
			if (url != null)
			{
				fetchImage(url, onSuccess, onError);
				return;
			}
			int colon = boss.indexOf(':');
			if (colon > 0)
			{
				fetchThumbnailUrl(boss.substring(0, colon).trim(), size, parentUrl ->
				{
					if (parentUrl == null)
					{
						onError.accept("No image");
					}
					else
					{
						fetchImage(parentUrl, onSuccess, onError);
					}
				}, onError);
			}
			else
			{
				onError.accept("No image");
			}
		}, onError);
	}

	private void fetchThumbnailUrl(String title, int size, Consumer<String> onResult, Consumer<String> onError)
	{
		okHttpClient.newCall(request(pageImageUrl(title, size))).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Page image request failed for {}", title, e);
				onError.accept("Could not reach the wiki");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						onError.accept("Wiki answered with HTTP " + response.code());
						return;
					}
					onResult.accept(parseThumbnail(gson, body.string()));
				}
				catch (IOException | JsonSyntaxException | IllegalStateException e)
				{
					log.debug("Page image response could not be read for {}", title, e);
					onError.accept("Wiki image could not be read");
				}
			}
		});
	}

	private void fetchImage(String url, Consumer<BufferedImage> onSuccess, Consumer<String> onError)
	{
		HttpUrl parsed = HttpUrl.parse(url);
		if (parsed == null || !WIKI_HOST.equals(parsed.host()))
		{
			onError.accept("Unexpected image host");
			return;
		}
		okHttpClient.newCall(request(parsed)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Image request failed for {}", url, e);
				onError.accept("Could not reach the wiki");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						onError.accept("Wiki answered with HTTP " + response.code());
						return;
					}
					BufferedImage image = ImageIO.read(body.byteStream());
					if (image == null)
					{
						onError.accept("Image could not be decoded");
						return;
					}
					onSuccess.accept(image);
				}
				catch (IOException e)
				{
					log.debug("Image could not be read from {}", url, e);
					onError.accept("Wiki image could not be read");
				}
			}
		});
	}
}

package com.calookup;

import java.util.Objects;

/**
 * One Combat Achievement task as read from the game cache. Immutable and safe to share
 * between the client thread and the Swing thread.
 */
public final class CombatTask
{
	private final int id;
	private final String name;
	private final String description;
	private final TaskTier tier;
	private final TaskType type;
	private final String boss;

	public CombatTask(int id, String name, String description, TaskTier tier, TaskType type, String boss)
	{
		this.id = id;
		this.name = name == null ? "" : name;
		this.description = description == null ? "" : description;
		this.tier = tier;
		this.type = type == null ? TaskType.UNKNOWN : type;
		this.boss = boss == null ? "" : boss;
	}

	/** The game's task ID. Also the key used by the wiki for completion rates. */
	public int getId()
	{
		return id;
	}

	/** Task title, e.g. {@code Noxious Foe}. Matches the task's page title on the wiki. */
	public String getName()
	{
		return name;
	}

	/** The in-game task text, e.g. {@code Kill an Aberrant Spectre.} */
	public String getDescription()
	{
		return description;
	}

	public TaskTier getTier()
	{
		return tier;
	}

	public TaskType getType()
	{
		return type;
	}

	/** The boss or monster group the game files this task under, e.g. {@code Zulrah}. */
	public String getBoss()
	{
		return boss;
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof CombatTask && ((CombatTask) o).id == id;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(id);
	}

	@Override
	public String toString()
	{
		return tier + " " + name + " (#" + id + ")";
	}
}

package com.calookup;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;

/**
 * One entry of the boss drop-down: a boss group with the points it offers and the points the
 * player has not earned yet. The list is ordered by points still available, so the bosses
 * with the most left to gain come first.
 */
final class BossOption
{
	/** Sentinel boss name for the entry that shows every task. */
	static final String ALL = "(All)";

	private final String boss;
	private final int totalPoints;
	private final int remainingPoints;
	private final boolean loggedIn;

	BossOption(String boss, int totalPoints, int remainingPoints, boolean loggedIn)
	{
		this.boss = boss;
		this.totalPoints = totalPoints;
		this.remainingPoints = remainingPoints;
		this.loggedIn = loggedIn;
	}

	String getBoss()
	{
		return boss;
	}

	int getTotalPoints()
	{
		return totalPoints;
	}

	int getRemainingPoints()
	{
		return remainingPoints;
	}

	/** Points still to gain when logged in, otherwise the boss's total. */
	int getAvailablePoints()
	{
		return loggedIn ? remainingPoints : totalPoints;
	}

	/** The text shown in the drop-down, e.g. {@code Zulrah  ·  22 pts left}. */
	String getLabel()
	{
		int pts = getAvailablePoints();
		return boss + "  ·  " + pts + (loggedIn ? (pts == 1 ? " pt left" : " pts left") : (pts == 1 ? " pt" : " pts"));
	}

	static boolean isAll(String boss)
	{
		return ALL.equals(boss);
	}

	/**
	 * Builds the drop-down entries: "(All)" first, then every boss ordered by points still
	 * available (descending) and name.
	 *
	 * @param bosses    boss display names
	 * @param tasksOf   tasks for each boss, in the same order as {@code bosses}
	 * @param allTasks  every task, for the "(All)" entry
	 * @param completed completed task IDs (empty when logged out)
	 * @param loggedIn  whether completion is known
	 */
	static List<BossOption> build(List<String> bosses, List<List<CombatTask>> tasksOf, List<CombatTask> allTasks,
		Set<Integer> completed, boolean loggedIn)
	{
		List<BossOption> options = new ArrayList<>();
		for (int i = 0; i < bosses.size(); i++)
		{
			List<CombatTask> tasks = tasksOf.get(i);
			int total = TaskArranger.pointsTotal(tasks);
			int remaining = total - TaskArranger.pointsDone(tasks, completed);
			options.add(new BossOption(bosses.get(i), total, remaining, loggedIn));
		}
		options.sort(Comparator.comparingInt(BossOption::getAvailablePoints).reversed()
			.thenComparing(BossOption::getBoss, String.CASE_INSENSITIVE_ORDER));

		int allTotal = TaskArranger.pointsTotal(allTasks);
		int allRemaining = allTotal - TaskArranger.pointsDone(allTasks, completed);
		options.add(0, new BossOption(ALL, allTotal, allRemaining, loggedIn));
		return options;
	}
}
